    #[test]
    fn double_double_nd_real_odd_even_compile_to_spirv_with_true_boundaries() {
        for last_len in [7usize, 8usize] {
            for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
                for transform in [
                    crate::TransformKind::RealToComplex,
                    crate::TransformKind::ComplexToReal,
                ] {
                    let plan = FftPlan::build(
                        FftConfig::new(vec![3, last_len])
                            .with_batch_count(7)
                            .with_transform(transform)
                            .with_precision(precision)
                            .with_inverse_normalization(
                                transform == crate::TransformKind::ComplexToReal,
                            )
                            .with_grouped_batch(0, 3)
                            .unwrap()
                            .with_grouped_batch(1, 3)
                            .unwrap(),
                    )
                    .unwrap();
                    let ir = crate::DoubleDoubleNdRealFftIr::build(&plan).unwrap();
                    assert_eq!(ir.real_axis.even_half_size, last_len.is_multiple_of(2));
                    assert_eq!(
                        ir.real_axis.external_storage,
                        crate::PrecisionStorage::DoubleDouble
                    );
                    let program = crate::ProgramIr::double_double_nd_real(&ir).unwrap();
                    let shaders = VulkanGlslBackend.lower_double_double_nd_real(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    let compact_last = last_len / 2 + 1;
                    assert_eq!(ir.real_grouped_batch, 3);
                    assert_eq!(ir.real_axis.grouped_batch, 3);
                    assert_eq!(ir.complex_axes[0].transform.grouped_batch(), 3);
                    assert_eq!(ir.batch_group_count(), 3);
                    assert!(program.passes.iter().any(|pass| pass.dispatch.x == 3));
                    assert!(program.passes.iter().any(|pass| pass.dispatch.x == 7));
                    let outer_groups = (7 * compact_last).div_ceil(3);
                    assert!(
                        program
                            .passes
                            .iter()
                            .any(|pass| pass.dispatch.x == outer_groups as u32)
                    );
                    assert!(
                        shaders
                            .iter()
                            .zip(&program.passes)
                            .all(|(shader, pass)| shader.dispatch == pass.dispatch)
                    );
                    assert!(shaders.iter().any(|shader| {
                        shader
                            .glsl
                            .contains("groupedBatch ownership: 3 tensor batches/workgroup")
                    }));
                    assert!(shaders.iter().any(|shader| shader.glsl.contains(&format!(
                        "3 tensor batches/workgroup, {} boundary packed transforms/workgroup; child groupedBatch 3",
                        3 * compact_last
                    ))));
                    assert!(
                        shaders
                            .iter()
                            .any(|shader| shader.glsl.contains("DD ND real axis 0 pack"))
                    );
                    assert!(
                        shaders
                            .iter()
                            .any(|shader| shader.glsl.contains("DD ND real axis 0 scatter"))
                    );
                    if last_len.is_multiple_of(2) {
                        assert!(shaders.iter().any(|shader| {
                            shader.glsl.contains("DD real R2C half-size pack")
                                || shader.glsl.contains("DD real C2R half-size preprocess")
                        }));
                    } else {
                        assert!(shaders.iter().any(|shader| {
                            shader.glsl.contains("DD real R2C promote")
                                || shader.glsl.contains("DD real C2R expand")
                        }));
                    }
                    let first = &shaders.first().unwrap().glsl;
                    let last = &shaders.last().unwrap().glsl;
                    match (precision, transform) {
                        (Precision::DoubleDouble, crate::TransformKind::RealToComplex) => {
                            assert!(first.contains("DD ND real R2C input copy"));
                            assert!(first.contains("VkFftInput { dvec2 data[]; }"));
                            assert!(last.contains("VkFftOutput { dvec4 data[]; }"));
                        }
                        (
                            Precision::DoubleDoubleF64Storage,
                            crate::TransformKind::RealToComplex,
                        ) => {
                            assert!(first.contains("DD ND real R2C input promote"));
                            assert!(first.contains("VkFftInput { double data[]; }"));
                            assert!(last.contains("VkFftOutput { dvec2 data[]; }"));
                        }
                        (Precision::DoubleDouble, crate::TransformKind::ComplexToReal) => {
                            assert!(first.contains("DD ND real C2R input copy"));
                            assert!(first.contains("VkFftInput { dvec4 data[]; }"));
                            assert!(last.contains("VkFftOutput { dvec2 data[]; }"));
                        }
                        (
                            Precision::DoubleDoubleF64Storage,
                            crate::TransformKind::ComplexToReal,
                        ) => {
                            assert!(first.contains("DD ND real C2R input promote"));
                            assert!(first.contains("VkFftInput { dvec2 data[]; }"));
                            assert!(last.contains("VkFftOutput { double data[]; }"));
                        }
                        _ => unreachable!(),
                    }
                    let mut no_contraction = 0usize;
                    for shader in &shaders {
                        let spirv = shader.compile_spirv().unwrap();
                        assert_eq!(spirv.words[0], 0x0723_0203);
                        let mut cursor = 5usize;
                        while cursor < spirv.words.len() {
                            let header = spirv.words[cursor];
                            let word_count = (header >> 16) as usize;
                            let opcode = (header & 0xffff) as u16;
                            assert!(word_count > 0 && cursor + word_count <= spirv.words.len());
                            if opcode == 71 && word_count >= 3 && spirv.words[cursor + 2] == 42 {
                                no_contraction += 1;
                            }
                            cursor += word_count;
                        }
                    }
                    assert!(
                        no_contraction > 0,
                        "DD ND real FFT must preserve NoContraction"
                    );
                }
            }
        }
    }

    #[test]
    fn double_double_nd_real_padding_fuses_into_full_real_boundary_and_compiles() {
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let config = FftConfig::new(vec![3, 8])
                    .with_batch_count(7)
                    .with_transform(transform)
                    .with_precision(precision)
                    .with_inverse_normalization(transform == crate::TransformKind::ComplexToReal)
                    .with_grouped_batch(0, 3)
                    .unwrap()
                    .with_grouped_batch(1, 3)
                    .unwrap()
                    .with_zero_padding(0, 1, 2)
                    .unwrap()
                    .with_zero_padding(1, 2, 4)
                    .unwrap();
                let plan = FftPlan::build(config).unwrap();
                let ir = crate::DoubleDoubleNdRealFftIr::build(&plan).unwrap();
                let program = crate::ProgramIr::double_double_nd_real(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_double_double_nd_real(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert_eq!(ir.real_grouped_batch, 3);
                assert_eq!(ir.real_axis.grouped_batch, 3);
                assert_eq!(ir.complex_axes[0].transform.grouped_batch(), 3);
                assert_eq!(ir.batch_group_count(), 3);
                assert!(program.passes.iter().any(|pass| pass.dispatch.x == 3));
                assert!(program.passes.iter().any(|pass| pass.dispatch.x == 7));
                assert!(program.passes.iter().any(|pass| pass.dispatch.x == 12));
                assert!(
                    shaders
                        .iter()
                        .zip(&program.passes)
                        .all(|(shader, pass)| shader.dispatch == pass.dispatch)
                );
                let zero_boundary_index = if transform == crate::TransformKind::RealToComplex {
                    0
                } else {
                    shaders.len() - 1
                };
                assert_eq!(
                    shaders
                        .iter()
                        .filter(|shader| shader
                            .glsl
                            .contains("fused spatial zero padding at full-real boundary"))
                        .count(),
                    1
                );
                let boundary = &shaders[zero_boundary_index].glsl;
                assert!(boundary.contains("fused spatial zero padding at full-real boundary"));
                assert!(boundary.contains("((lane / 1u) % 8u) >= 2u"));
                assert!(boundary.contains("((lane / 8u) % 3u) >= 1u"));
                assert!(boundary.contains("?"));
                match (precision, transform) {
                    (Precision::DoubleDouble, crate::TransformKind::RealToComplex) => {
                        assert!(boundary.contains("VkFftInput { dvec2 data[]; }"));
                        assert!(boundary.contains("dvec2(0.0)"));
                    }
                    (Precision::DoubleDoubleF64Storage, crate::TransformKind::RealToComplex) => {
                        assert!(boundary.contains("VkFftInput { double data[]; }"));
                        assert!(boundary.contains("dvec2(0.0)"));
                    }
                    (Precision::DoubleDouble, crate::TransformKind::ComplexToReal) => {
                        assert!(boundary.contains("VkFftOutput { dvec2 data[]; }"));
                        assert!(boundary.contains("dvec2(0.0)"));
                    }
                    (Precision::DoubleDoubleF64Storage, crate::TransformKind::ComplexToReal) => {
                        assert!(boundary.contains("VkFftOutput { double data[]; }"));
                        assert!(boundary.contains("? 0.0 :"));
                    }
                    _ => unreachable!(),
                }
                for shader in &shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn double_double_real_padding_odd_even_fuses_true_spatial_boundaries() {
        for length in [15usize, 16usize] {
            for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
                for transform in [
                    crate::TransformKind::RealToComplex,
                    crate::TransformKind::ComplexToReal,
                ] {
                    let config = FftConfig::new(vec![length])
                        .with_batch_count(7)
                        .with_transform(transform)
                        .with_precision(precision)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        )
                        .with_grouped_batch(0, 3)
                        .unwrap()
                        .with_zero_padding(0, 3, 7)
                        .unwrap();
                    let ir = crate::DoubleDoubleRealFftIr::build(&FftPlan::build(config).unwrap())
                        .unwrap();
                    let program = crate::ProgramIr::double_double_real(&ir).unwrap();
                    let shaders = VulkanGlslBackend.lower_double_double_real(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    assert_eq!(ir.grouped_batch, 3);
                    assert_eq!(ir.transform.grouped_batch(), 3);
                    assert_eq!(ir.batch_group_count(), 3);
                    assert!(program.passes.iter().all(|pass| pass.dispatch.x == 3));
                    assert!(shaders.iter().all(|shader| shader.dispatch.x == 3));
                    assert!(shaders.iter().any(|shader| {
                        shader
                            .glsl
                            .contains("groupedBatch ownership: 3 transforms/workgroup")
                    }));
                    let boundary_index = if transform == crate::TransformKind::RealToComplex {
                        0
                    } else {
                        shaders.len() - 1
                    };
                    let marker = if length.is_multiple_of(2) {
                        "fused spatial zero padding at DD real half-size boundary"
                    } else {
                        "fused spatial zero padding at DD real boundary"
                    };
                    assert_eq!(
                        shaders
                            .iter()
                            .filter(|shader| shader.glsl.contains(marker))
                            .count(),
                        1
                    );
                    let boundary = &shaders[boundary_index].glsl;
                    assert!(boundary.contains(marker));
                    if length.is_multiple_of(2) {
                        assert!(boundary.contains("(2u * j) >= 3u"));
                        assert!(boundary.contains("(2u * j) < 7u"));
                        assert!(boundary.contains("(2u * j + 1u) >= 3u"));
                        assert!(boundary.contains("(2u * j + 1u) < 7u"));
                    } else {
                        assert!(boundary.contains("i >= 3u && i < 7u"));
                    }
                    match (precision, transform) {
                        (Precision::DoubleDouble, crate::TransformKind::RealToComplex) => {
                            assert!(boundary.contains("VkFftInput { dvec2 data[]; }"));
                        }
                        (
                            Precision::DoubleDoubleF64Storage,
                            crate::TransformKind::RealToComplex,
                        ) => {
                            assert!(boundary.contains("VkFftInput { double data[]; }"));
                        }
                        (Precision::DoubleDouble, crate::TransformKind::ComplexToReal) => {
                            assert!(boundary.contains("VkFftOutput { dvec2 data[]; }"));
                        }
                        (
                            Precision::DoubleDoubleF64Storage,
                            crate::TransformKind::ComplexToReal,
                        ) => {
                            assert!(boundary.contains("VkFftOutput { double data[]; }"));
                        }
                        _ => unreachable!(),
                    }
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }
            }
        }
    }

    #[test]
    fn double_double_even_real_n16_lowers_half_size_boundaries_to_spirv() {
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for (transform, kind) in [
                (
                    crate::TransformKind::RealToComplex,
                    crate::RealFftKind::RealToComplex,
                ),
                (
                    crate::TransformKind::ComplexToReal,
                    crate::RealFftKind::ComplexToReal,
                ),
            ] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![16])
                        .with_batch_count(2)
                        .with_transform(transform)
                        .with_precision(precision)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        ),
                )
                .unwrap();
                let ir = crate::DoubleDoubleRealFftIr::build(&plan).unwrap();
                assert_eq!(ir.kind, kind);
                assert!(ir.even_half_size);
                assert_eq!(ir.transform.sequence_len(), 8);
                assert_eq!(ir.even_roots.len(), 9);
                let program = crate::ProgramIr::double_double_real(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_double_double_real(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert_eq!(
                    shaders.len(),
                    crate::ProgramIr::double_double_one_dim(&ir.transform)
                        .unwrap()
                        .passes
                        .len()
                        + 2
                );
                let first = &shaders[0].glsl;
                let last = &shaders[shaders.len() - 1].glsl;
                match transform {
                    crate::TransformKind::RealToComplex => {
                        assert_eq!(program.passes.first().unwrap().bindings.len(), 2);
                        assert_eq!(program.passes.last().unwrap().bindings.len(), 3);
                        assert!(last.contains("VkFftRealRoots"));
                    }
                    crate::TransformKind::ComplexToReal => {
                        assert_eq!(program.passes.first().unwrap().bindings.len(), 3);
                        assert_eq!(program.passes.last().unwrap().bindings.len(), 2);
                        assert!(first.contains("VkFftRealRoots"));
                    }
                    _ => unreachable!(),
                }
                match (precision, transform) {
                    (Precision::DoubleDouble, crate::TransformKind::RealToComplex) => {
                        assert!(first.contains("DD real R2C half-size pack"));
                        assert!(first.contains("VkFftInput { dvec2 data[]; }"));
                        assert!(first.contains("VkFftOutput { dvec4 data[]; }"));
                        assert!(last.contains("DD real R2C half-size postprocess"));
                        assert!(last.contains("VkFftOutput { dvec4 data[]; }"));
                    }
                    (Precision::DoubleDoubleF64Storage, crate::TransformKind::RealToComplex) => {
                        assert!(first.contains("VkFftInput { double data[]; }"));
                        assert!(first.contains("VkFftOutput { dvec4 data[]; }"));
                        assert!(last.contains("VkFftOutput { dvec2 data[]; }"));
                    }
                    (Precision::DoubleDouble, crate::TransformKind::ComplexToReal) => {
                        assert!(first.contains("DD real C2R half-size preprocess"));
                        assert!(first.contains("VkFftInput { dvec4 data[]; }"));
                        assert!(last.contains("DD real C2R half-size unpack"));
                        assert!(last.contains("VkFftOutput { dvec2 data[]; }"));
                    }
                    (Precision::DoubleDoubleF64Storage, crate::TransformKind::ComplexToReal) => {
                        assert!(first.contains("VkFftInput { dvec2 data[]; }"));
                        assert!(first.contains("VkFftOutput { dvec4 data[]; }"));
                        assert!(last.contains("VkFftOutput { double data[]; }"));
                    }
                    _ => unreachable!(),
                }
                let mut no_contraction = 0usize;
                for shader in &shaders {
                    let spirv = shader.compile_spirv().unwrap();
                    assert_eq!(spirv.words[0], 0x0723_0203);
                    let mut cursor = 5usize;
                    while cursor < spirv.words.len() {
                        let header = spirv.words[cursor];
                        let word_count = (header >> 16) as usize;
                        let opcode = (header & 0xffff) as u16;
                        assert!(word_count > 0 && cursor + word_count <= spirv.words.len());
                        if opcode == 71 && word_count >= 3 && spirv.words[cursor + 2] == 42 {
                            no_contraction += 1;
                        }
                        cursor += word_count;
                    }
                }
                assert!(
                    no_contraction > 0,
                    "DD real internal FFT must preserve NoContraction"
                );
            }
        }
    }

