    #[test]
    fn double_double_nd_3x4_lowers_pack_stockham_scatter_to_spirv() {
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            let plan = FftPlan::build(
                FftConfig::new(vec![3, 4])
                    .with_batch_count(2)
                    .with_precision(precision),
            )
            .unwrap();
            let ir = crate::DoubleDoubleNdFftIr::build(&plan, Direction::Forward).unwrap();
            let program = crate::ProgramIr::double_double_nd(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_double_double_nd(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            assert!(shaders.first().unwrap().glsl.contains("ND axis 1 pack"));
            assert!(shaders.last().unwrap().glsl.contains("ND axis 0 scatter"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(
                        shaders
                            .first()
                            .unwrap()
                            .glsl
                            .contains("VkFftInput { dvec4 data[]; }")
                    );
                    assert!(
                        shaders
                            .last()
                            .unwrap()
                            .glsl
                            .contains("VkFftOutput { dvec4 data[]; }")
                    );
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(
                        shaders
                            .first()
                            .unwrap()
                            .glsl
                            .contains("VkFftInput { dvec2 data[]; }")
                    );
                    assert!(
                        shaders
                            .first()
                            .unwrap()
                            .glsl
                            .contains("dvec4((vkfft_input.data[natural]).x, 0.0, (vkfft_input.data[natural]).y, 0.0)")
                    );
                    assert!(
                        shaders
                            .last()
                            .unwrap()
                            .glsl
                            .contains("VkFftOutput { dvec2 data[]; }")
                    );
                    assert!(shaders.last().unwrap().glsl.contains(
                        "dvec2((vkfft_input.data[packed]).x, (vkfft_input.data[packed]).z)"
                    ));
                }
                _ => unreachable!(),
            }
            let mut no_contraction = 0usize;
            for shader in &shaders {
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
                let mut cursor = 5usize;
                while cursor < spirv.words.len() {
                    let header = spirv.words[cursor];
                    let word_count = (header >> 16) as usize;
                    let opcode = (header & 0xffff) as u16;
                    assert!(word_count > 0 && cursor + word_count <= spirv.words.len());
                    if opcode == 71 && word_count >= 3 && spirv.words[cursor + 2] == 42 {
                        no_contraction += 1;
                    }
                    cursor += word_count;
                }
            }
            assert!(
                no_contraction > 0,
                "DD ND SPIR-V must forbid contraction in FFT stages"
            );
        }
    }

    #[test]
    fn double_double_nd_padding_fuses_into_directional_external_boundary() {
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for direction in [Direction::Forward, Direction::Inverse] {
                let config = FftConfig::new(vec![3, 4])
                    .with_batch_count(2)
                    .with_precision(precision)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(0, 1, 2)
                    .unwrap()
                    .with_zero_padding(1, 1, 3)
                    .unwrap();
                let ir =
                    crate::DoubleDoubleNdFftIr::build(&FftPlan::build(config).unwrap(), direction)
                        .unwrap();
                let program = crate::ProgramIr::double_double_nd(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_double_double_nd(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                let zero_index = if direction == Direction::Forward {
                    0
                } else {
                    shaders.len() - 1
                };
                assert_eq!(
                    shaders
                        .iter()
                        .filter(|shader| shader
                            .glsl
                            .contains("fused spatial zero padding at DD ND true boundary"))
                        .count(),
                    1
                );
                let boundary = &shaders[zero_index].glsl;
                assert!(boundary.contains("uint spatial = natural - batch * 12u"));
                assert!(boundary.contains("((spatial / 1u) % 4u) >= 1u"));
                assert!(boundary.contains("((spatial / 4u) % 3u) >= 1u"));
                match (precision, direction) {
                    (Precision::DoubleDouble, Direction::Forward) => {
                        assert!(boundary.contains("VkFftInput { dvec4 data[]; }"));
                        assert!(boundary.contains("? dvec4(0.0) :"));
                    }
                    (Precision::DoubleDoubleF64Storage, Direction::Forward) => {
                        assert!(boundary.contains("VkFftInput { dvec2 data[]; }"));
                        assert!(boundary.contains("? dvec4(0.0) :"));
                    }
                    (Precision::DoubleDouble, Direction::Inverse) => {
                        assert!(boundary.contains("VkFftOutput { dvec4 data[]; }"));
                        assert!(boundary.contains("? dvec4(0.0) :"));
                    }
                    (Precision::DoubleDoubleF64Storage, Direction::Inverse) => {
                        assert!(boundary.contains("VkFftOutput { dvec2 data[]; }"));
                        assert!(boundary.contains("? dvec2(0.0) :"));
                    }
                    _ => unreachable!(),
                }
                for shader in &shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

