    #[test]
    fn broader_power_of_two_rader_grouping_lowers_without_semantic_shortcuts() {
        let device = full_subgroup_device();
        let batch_count = 2usize;

        // Four p257 convolution containers execute as one 64-thread workgroup. The
        // exact 32-lane two-container ownership proof repeats across both full
        // subgroups; SubgroupId/SubgroupInvocationId reconstruct logical container/lane
        // ownership without assuming local-invocation order inside a subgroup.
        let plan =
            FftPlan::build(FftConfig::new(vec![1028]).with_batch_count(batch_count)).unwrap();
        let mixed = crate::MixedRaderStockhamIr::build(&plan, Direction::Forward, device).unwrap();
        let crate::MixedPrimeRaderIr::FftConvolution(rader) = &mixed.prime_stage else {
            panic!("1028 should use FFT-convolution Rader for its p257 factor");
        };
        let schedule = rader.internal_register_schedule.as_ref().unwrap();
        assert_eq!(schedule.container_fft_num, 4);
        assert_eq!(schedule.execution_container_fft_num, 4);
        assert_eq!(schedule.execution_threads_per_workgroup, 64);
        assert!(schedule.rader_transpose.is_none());
        let RecursiveFftNodeIr::Stockham(kernel) = &rader.forward_recursive().unwrap().root else {
            panic!("grouped p257 convolution should remain a Stockham root");
        };
        assert_eq!(kernel.workgroup_grouping.transforms_per_workgroup, 4);
        assert_eq!(kernel.workgroup_grouping.threads_per_transform, 16);
        assert_eq!(kernel.workgroup_size.x, 64);
        assert_eq!(kernel.dispatch.x as usize, batch_count);
        assert_eq!(kernel.shared_memory.elements_per_buffer, 272 * 4);
        let shader = VulkanGlslBackend
            .lower_one_dim_fft(&rader.forward_fft)
            .unwrap()
            .remove(0);
        assert_eq!(shader.workgroup_size.x, 64);
        assert_eq!(shader.dispatch.x as usize, batch_count);
        assert_eq!(shader.required_shared_memory_bytes, 0);
        assert_eq!(shader.required_subgroup_size, Some(32));
        assert!(shader.glsl.contains("Full-subgroup contract"));
        assert!(shader.glsl.contains("VKFFT_TRANSFORMS_PER_WORKGROUP = 4u"));
        assert!(shader.glsl.contains("VKFFT_TRANSFORMS_PER_SUBGROUP = 2u"));
        assert!(shader.glsl.contains("VKFFT_SUBGROUP_COUNT = 2u"));
        assert!(shader.glsl.contains(SUBGROUP_INVOCATION_ID_MARKER));
        assert!(shader.glsl.contains(SUBGROUP_ID_MARKER));
        assert!(!shader.glsl.contains("shared vec2 vkfft_smem_a"));
        let spirv = shader.compile_spirv().unwrap();
        assert!(spirv.require_full_subgroups);
        assert_eq!(spirv.required_shared_memory_bytes, 0);
        assert_eq!(spirv.required_subgroup_size, Some(32));

        let f64_plan = FftPlan::build(
            FftConfig::new(vec![1028])
                .with_batch_count(batch_count)
                .with_precision(Precision::F64),
        )
        .unwrap();
        let f64_mixed =
            crate::MixedRaderStockhamIr::build(&f64_plan, Direction::Forward, device).unwrap();
        let crate::MixedPrimeRaderIr::FftConvolution(f64_rader) = &f64_mixed.prime_stage else {
            panic!("F64 1028 should use FFT-convolution Rader");
        };
        let f64_shader = VulkanGlslBackend
            .lower_one_dim_fft(&f64_rader.forward_fft)
            .unwrap()
            .remove(0);
        assert!(f64_shader.glsl.contains("dvec2"));
        assert_eq!(f64_shader.required_shared_memory_bytes, 0);
        assert_eq!(f64_shader.required_subgroup_size, Some(32));
        let f64_spirv = f64_shader.compile_spirv().unwrap();
        assert!(f64_spirv.require_full_subgroups);
        assert_eq!(f64_spirv.required_shared_memory_bytes, 0);
        assert_eq!(f64_spirv.required_subgroup_size, Some(32));

        // Eight p17 containers have a single radix-16 stage. Upstream does not
        // enable raderTranspose for a one-stage container, and the Rust register
        // lowering has no inter-stage exchange at all, so shared memory is exactly 0.
        let short_plan =
            FftPlan::build(FftConfig::new(vec![136]).with_batch_count(batch_count)).unwrap();
        let short_mixed =
            crate::MixedRaderStockhamIr::build(&short_plan, Direction::Forward, device).unwrap();
        let crate::MixedPrimeRaderIr::FftConvolution(short_rader) = &short_mixed.prime_stage else {
            panic!("136 should use FFT-convolution Rader for its p17 factor");
        };
        let short_schedule = short_rader.internal_register_schedule.as_ref().unwrap();
        assert_eq!(short_schedule.container_fft_num, 8);
        assert_eq!(short_schedule.execution_container_fft_num, 8);
        assert_eq!(short_schedule.execution_threads_per_workgroup, 8);
        assert!(short_schedule.rader_transpose.is_none());
        let RecursiveFftNodeIr::Stockham(short_kernel) =
            &short_rader.forward_recursive().unwrap().root
        else {
            panic!("grouped p17 convolution should remain a Stockham root");
        };
        assert_eq!(short_kernel.workgroup_grouping.transforms_per_workgroup, 8);
        assert_eq!(short_kernel.workgroup_grouping.threads_per_transform, 1);
        assert_eq!(short_kernel.workgroup_size.x, 8);
        let short_shader = VulkanGlslBackend
            .lower_one_dim_fft(&short_rader.forward_fft)
            .unwrap()
            .remove(0);
        assert_eq!(short_shader.workgroup_size.x, 8);
        assert_eq!(short_shader.dispatch.x as usize, batch_count);
        assert_eq!(short_shader.required_shared_memory_bytes, 0);
        assert!(!short_shader.glsl.contains("shared vec2 vkfft_smem_a"));
        let short_spirv = short_shader.compile_spirv().unwrap();
        assert_eq!(short_spirv.required_shared_memory_bytes, 0);
        assert!(!short_spirv.require_full_subgroups);
    }

    #[test]
    fn variable_uncontrolled_subgroup_width_keeps_grouped_rader_shared_fallback() {
        let mut device = full_subgroup_device();
        device.subgroup.min_size = 16;
        device.subgroup.max_size = 32;
        device.subgroup.required_size_compute_supported = false;
        assert!(!device.subgroup.supports_full_subgroup_shuffle_compute());

        let plan = FftPlan::build(FftConfig::new(vec![1028]).with_batch_count(2)).unwrap();
        let mixed = crate::MixedRaderStockhamIr::build(&plan, Direction::Forward, device).unwrap();
        let crate::MixedPrimeRaderIr::FftConvolution(rader) = &mixed.prime_stage else {
            panic!("1028 should still use FFT-convolution Rader");
        };
        let shader = VulkanGlslBackend
            .lower_one_dim_fft(&rader.forward_fft)
            .unwrap()
            .remove(0);
        assert_eq!(shader.workgroup_size.x, 64);
        assert!(shader.required_shared_memory_bytes > 0);
        assert_eq!(shader.required_subgroup_size, None);
        assert!(!shader.glsl.contains(SUBGROUP_INVOCATION_ID_MARKER));
        assert!(!shader.glsl.contains(SUBGROUP_ID_MARKER));
        let spirv = shader.compile_spirv().unwrap();
        assert!(!spirv.require_full_subgroups);
        assert_eq!(spirv.required_subgroup_size, None);
        assert!(spirv.required_shared_memory_bytes > 0);
    }

    #[test]
    fn recursive_rader_trees_lower_in_program_order_and_compile_to_spirv() {
        for (length, expected_passes) in [(289usize, 7usize), (323, 7), (578, 8)] {
            let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.shared_memory_bytes = 128 * 1024;
            let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
            let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
            assert_eq!(shaders.len(), expected_passes);
            assert_eq!(shaders.len(), program.passes.len());
            for (shader, pass) in shaders.iter().zip(&program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.descriptors.len(), pass.bindings.len());
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn nested_sub_rader_tree_lowers_grouped_child_and_compiles_to_spirv() {
        let plan = FftPlan::build(
            FftConfig::new(vec![107])
                .with_tuning(crate::PlannerTuning::portable().with_recursive_fft_rader(true)),
        )
        .unwrap();
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
        let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());
        assert!(shaders.iter().any(|shader| {
            shader.sequence_len == 106
                && shader.glsl.contains("VKFFT_RADER_PRIME = 107u")
                && shader.glsl.contains("VKFFT_RADER_PERM")
        }));
        let grouped_sub_rader = shaders
            .iter()
            .filter(|shader| shader.sequence_len == 52)
            .collect::<Vec<_>>();
        assert!(!grouped_sub_rader.is_empty());
        assert!(grouped_sub_rader.iter().any(|shader| {
            shader.workgroup_size.x == 8
                && shader.glsl.contains("VKFFT_TRANSFORMS_PER_WORKGROUP = 2u")
        }));
        assert!(shaders.iter().any(|shader| {
            shader.sequence_len == 106
                && shader.descriptors.len() == 3
                && shader.descriptors[2].role == BufferRole::LookupTable
        }));
        assert!(shaders.iter().any(|shader| {
            shader.sequence_len == 106
                && shader.descriptors.len() == 3
                && shader.descriptors[2].role == BufferRole::Auxiliary
                && shader.glsl.contains("rader_dc")
        }));
        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn constrained_nested_rader_child_preserves_device_selected_direct_mode_to_spirv() {
        let plan = FftPlan::build(
            FftConfig::new(vec![107])
                .with_tuning(crate::PlannerTuning::portable().with_recursive_fft_rader(true)),
        )
        .unwrap();
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 256;
        device.shared_memory_pow2_bytes = 256;
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
        let crate::RecursiveFftNodeIr::FftRader(outer) = &ir.root else {
            panic!("p107 should remain an outer FFT-Rader leaf");
        };
        let crate::RecursiveFftNodeIr::CooleyTukey(convolution) =
            &outer.forward_recursive().unwrap().root
        else {
            panic!("p107 convolution should split 106 as 2 x 53");
        };
        assert_eq!((convolution.left_len, convolution.right_len), (2, 53));
        assert!(matches!(
            convolution.right,
            crate::RecursiveFftNodeIr::DirectRader(_)
        ));

        let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());
        let direct_p53 = shaders
            .iter()
            .filter(|shader| {
                shader.sequence_len == 53
                    && shader
                        .glsl
                        .contains("generated by vkfft-rs from typed RaderDirectIr")
            })
            .collect::<Vec<_>>();
        assert!(!direct_p53.is_empty());
        assert!(direct_p53.iter().all(|shader| {
            shader.required_shared_memory_bytes == 0
                && shader.descriptors.len() == 3
                && shader.descriptors[2].role == BufferRole::LookupTable
        }));
        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn fft_rader_with_bluestein_convolution_child_compiles_to_spirv() {
        let mut tuning = crate::PlannerTuning::portable();
        tuning.min_rader_direct_prime = 29;
        tuning.min_rader_fft_prime = 29;
        tuning.validate().unwrap();
        let plan = FftPlan::build(FftConfig::new(vec![103]).with_tuning(tuning)).unwrap();
        let ir =
            crate::OneDimFftIr::build(&plan, Direction::Forward, full_subgroup_device()).unwrap();
        let crate::OneDimFftIr::Recursive(recursive) = &ir else {
            panic!("custom p103 should keep an outer recursive FFT-Rader node");
        };
        let crate::RecursiveFftNodeIr::FftRader(rader) = &recursive.root else {
            panic!("custom p103 should keep an FFT-Rader root");
        };
        assert_eq!(
            rader.input_strategy,
            RaderFftInputStrategy::GatherReversePass
        );
        assert!(matches!(
            rader.forward_fft.as_ref(),
            crate::OneDimFftIr::Bluestein(_)
        ));
        assert!(matches!(
            rader.inverse_fft.as_ref(),
            crate::OneDimFftIr::Bluestein(_)
        ));

        let program = crate::ProgramIr::one_dim_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_one_dim_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());
        assert!(
            shaders.len() >= 9,
            "Rader + two Bluestein children should be multi-pass"
        );
        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

