    #[test]
    fn forced_rader_fft_upload_compiles_mapped_grouped_boundary_to_spirv() {
        let length = 17usize * 31 * 64;
        let batch_count = 5usize;
        let plan = FftPlan::build(
            FftConfig::new(vec![length])
                .with_batch_count(batch_count)
                .with_grouped_batch(0, 3)
                .unwrap()
                .with_precision(Precision::F16StorageF32Compute),
        )
        .unwrap();
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 4 * 1024;
        device.shared_memory_pow2_bytes = 4 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
        assert_eq!(
            ir.rader_forced_upload_schedule.as_ref().unwrap().axis_split,
            vec![32, 34, 31]
        );
        let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());

        let forward = shaders
            .iter()
            .find(|shader| {
                shader.sequence_len == 30 && shader.glsl.contains("VKFFT_RADER_PERM[30]")
            })
            .expect(
                "31-point forced high upload should fuse mapped Rader gather into forward Stockham",
            );
        assert!(forward.glsl.contains("VKFFT_FOUR_STEP_B = 34u"));
        assert!(forward.glsl.contains("VKFFT_FOUR_STEP_C = 31u"));
        assert!(forward.glsl.contains("VKFFT_FOUR_STEP_AB = 1088u"));
        assert_eq!(forward.descriptors.len(), 2);
        assert!(!shaders.iter().any(|shader| {
            shader.sequence_len == 31
                && shader.descriptors.len() == 2
                && shader.glsl.contains("VKFFT_RADER_PERM[30]")
        }));
        assert_eq!(forward.dispatch.x, 340);

        let scatter = shaders
            .iter()
            .find(|shader| {
                shader.sequence_len == 31
                    && shader.descriptors.len() == 3
                    && shader.glsl.contains("VKFFT_FOUR_STEP_A = 32u")
                    && shader
                        .glsl
                        .contains("VKFFT_FOUR_STEP_A * VKFFT_FOUR_STEP_B")
            })
            .expect("31-point forced high upload should lower mapped FFT-Rader scatter");
        assert_eq!(scatter.dispatch, forward.dispatch);

        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn forced_rader_direct_upload_compiles_four_step_mapping_to_spirv() {
        let length = 17usize * 47 * 128;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 4 * 1024;
        device.shared_memory_pow2_bytes = 4 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
        assert_eq!(
            ir.rader_forced_upload_schedule.as_ref().unwrap().axis_split,
            vec![64, 47, 34]
        );
        let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());

        let direct = shaders
            .iter()
            .find(|shader| {
                shader.sequence_len == 47 && shader.glsl.contains("VKFFT_RADER_PERM[46]")
            })
            .expect("47-point forced middle upload should lower as direct Rader");
        assert!(direct.glsl.contains("VKFFT_FOUR_STEP_FULL_N = 102272u"));
        assert!(direct.glsl.contains("VKFFT_FOUR_STEP_A = 64u"));
        assert!(direct.glsl.contains("VKFFT_FOUR_STEP_B = 47u"));
        assert!(direct.glsl.contains("VKFFT_FOUR_STEP_C = 34u"));
        assert!(direct.glsl.contains("vkfft_batch / VKFFT_FOUR_STEP_A"));
        assert!(
            direct
                .glsl
                .contains("VKFFT_FOUR_STEP_A * VKFFT_FOUR_STEP_B")
        );

        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn grouped_composite_rader_root_compiles_parent_tail_to_spirv() {
        let length = 34usize;
        let batch_count = 5usize;
        let grouped_batch = 3usize;
        let mut device = full_subgroup_device();
        device.max_workgroup_size = [1024, 1024, 64];

        for (direction, padded) in [
            (Direction::Forward, false),
            (Direction::Forward, true),
            (Direction::Inverse, true),
        ] {
            let mut config = FftConfig::new(vec![length])
                .with_batch_count(batch_count)
                .with_grouped_batch(0, grouped_batch)
                .unwrap()
                .with_precision(Precision::F16StorageF32Compute)
                .with_inverse_normalization(direction == Direction::Inverse);
            if padded {
                config = config.with_zero_padding(0, 7, 12).unwrap();
            }
            let plan = FftPlan::build(config).unwrap();
            let ir = crate::RecursiveFftIr::build(&plan, direction, device).unwrap();
            assert!(ir.four_step_plan.is_none());
            let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let root_grouped = shaders
                .iter()
                .filter(|shader| {
                    shader.sequence_len == length
                        && shader.glsl.contains("VKFFT_GROUPED_BATCH = 3u")
                })
                .collect::<Vec<_>>();
            assert_eq!(
                root_grouped.len(),
                if direction == Direction::Inverse {
                    1
                } else {
                    3
                }
            );
            assert!(root_grouped.iter().all(|shader| {
                shader.dispatch.x == 2
                    && shader
                        .glsl
                        .contains("vkfft_batch = gl_WorkGroupID.x * VKFFT_GROUPED_BATCH")
                    && shader
                        .glsl
                        .contains("if (vkfft_batch >= VKFFT_BATCH_COUNT) { return; }")
            }));
            assert_eq!(
                shaders
                    .iter()
                    .filter(|shader| {
                        shader.sequence_len == 2 && shader.glsl.contains("VKFFT_COOLEY_N = 34u")
                    })
                    .count(),
                if direction == Direction::Inverse {
                    1
                } else {
                    0
                }
            );
            for (shader, pass) in shaders.iter().zip(&program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.descriptors.len(), pass.bindings.len());
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

