    #[test]
    fn forced_rader_four_step_mixed_storage_and_padding_compile_to_spirv() {
        let length = 17usize * 300;
        let mut device = full_subgroup_device();
        device.max_threads_per_block = 128;
        device.shared_memory_bytes = 48 * 1024;
        device.shared_memory_pow2_bytes = 32 * 1024;

        for (direction, padded) in [
            (Direction::Forward, false),
            (Direction::Forward, true),
            (Direction::Inverse, true),
        ] {
            let mut config = FftConfig::new(vec![length])
                .with_precision(Precision::F16StorageF32Compute)
                .with_inverse_normalization(direction == Direction::Inverse);
            if padded {
                config = config.with_zero_padding(0, 211, 317).unwrap();
            }
            let plan = FftPlan::build(config).unwrap();
            let one_dim = crate::OneDimFftIr::build(&plan, direction, device).unwrap();
            let crate::OneDimFftIr::Recursive(recursive) = &one_dim else {
                panic!("forced-Rader mixed-storage probe should remain recursive");
            };
            assert_eq!(
                recursive
                    .rader_forced_upload_schedule
                    .as_ref()
                    .unwrap()
                    .axis_split,
                vec![68, 75]
            );
            assert_eq!(
                recursive
                    .four_step_rader_upload_nodes()
                    .unwrap()
                    .expect("mixed-storage forced Rader plan should retain Four-step nodes")
                    .len(),
                2
            );

            let program = crate::ProgramIr::one_dim_fft(&one_dim).unwrap();
            assert_eq!(program.input_resource().unwrap().scalar, ScalarType::F16);
            assert_eq!(program.output_resource().unwrap().scalar, ScalarType::F16);
            assert!(program.resources.iter().all(|resource| {
                matches!(
                    resource.kind,
                    crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                ) || resource.scalar == ScalarType::F32
            }));
            let shaders = VulkanGlslBackend.lower_one_dim_fft(&one_dim).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            for (shader, pass) in shaders.iter().zip(&program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.descriptors.len(), pass.bindings.len());
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn grouped_forced_rader_mixed_padding_keeps_directional_resources_to_spirv() {
        let length = 17usize * 8192;
        let batch_count = 5usize;
        let grouped_batch = 3usize;
        let mut device = full_subgroup_device();
        device.max_workgroup_size = [1024, 1024, 64];

        for direction in [Direction::Forward, Direction::Inverse] {
            let config = FftConfig::new(vec![length])
                .with_batch_count(batch_count)
                .with_grouped_batch(0, grouped_batch)
                .unwrap()
                .with_precision(Precision::F16StorageF32Compute)
                .with_inverse_normalization(direction == Direction::Inverse)
                .with_zero_padding(0, 12_000, 12_700)
                .unwrap();
            let plan = FftPlan::build(config).unwrap();
            let one_dim = crate::OneDimFftIr::build(&plan, direction, device).unwrap();
            let crate::OneDimFftIr::Recursive(recursive) = &one_dim else {
                panic!("grouped mixed-padding forced-Rader probe should remain recursive");
            };
            assert_eq!(recursive.axis0_grouped_batch_override, Some(grouped_batch));
            assert_eq!(
                recursive
                    .rader_forced_upload_schedule
                    .as_ref()
                    .unwrap()
                    .axis_split,
                vec![512, 272]
            );
            let four_step = recursive.four_step_plan.as_ref().unwrap();
            assert!(
                four_step
                    .uploads
                    .iter()
                    .all(|upload| upload.axis_block.is_some())
            );
            assert_eq!(
                four_step.uploads[1].axis_block.unwrap().grouped_batch,
                grouped_batch
            );
            assert!(
                !four_step.uploads[1]
                    .transform_count
                    .is_multiple_of(grouped_batch)
            );
            assert!(recursive.four_step_rader_upload_nodes().unwrap().is_some());

            let program = crate::ProgramIr::one_dim_fft(&one_dim).unwrap();
            assert_eq!(program.input_resource().unwrap().scalar, ScalarType::F16);
            assert_eq!(program.output_resource().unwrap().scalar, ScalarType::F16);
            assert!(program.resources.iter().all(|resource| {
                matches!(
                    resource.kind,
                    crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                ) || resource.scalar == ScalarType::F32
            }));
            let zero_pad_index = match direction {
                Direction::Forward => 0,
                Direction::Inverse => program.passes.len() - 1,
            };
            let zero_pad = &program.passes[zero_pad_index];
            assert!(zero_pad.name.contains("zero_pad"));
            let zero_input = &program.resources[zero_pad.bindings[0].resource.0];
            let zero_output = &program.resources[zero_pad.bindings[1].resource.0];
            assert_eq!(
                (zero_input.scalar, zero_output.scalar),
                match direction {
                    Direction::Forward => (ScalarType::F16, ScalarType::F32),
                    Direction::Inverse => (ScalarType::F32, ScalarType::F16),
                }
            );

            let shaders = VulkanGlslBackend.lower_one_dim_fft(&one_dim).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let grouped_cooley = shaders
                .iter()
                .filter(|shader| {
                    shader.sequence_len == 272 && shader.glsl.contains("VKFFT_GROUPED_BATCH")
                })
                .collect::<Vec<_>>();
            assert_eq!(grouped_cooley.len(), 3);
            assert!(grouped_cooley.iter().all(|shader| {
                shader
                    .glsl
                    .contains("if (vkfft_batch >= VKFFT_BATCH_COUNT) { return; }")
            }));
            for (shader, pass) in shaders.iter().zip(&program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.descriptors.len(), pass.bindings.len());
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn multidimensional_real_and_r2r_lower_in_program_order() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let r2c_plan = FftPlan::build(
            FftConfig::new(vec![3, 8]).with_transform(crate::TransformKind::RealToComplex),
        )
        .unwrap();
        let r2c = crate::NdRealFftIr::build(&r2c_plan, device).unwrap();
        let r2c_program = crate::ProgramIr::nd_real_fft(&r2c).unwrap();
        let r2c_shaders = VulkanGlslBackend.lower_nd_real_fft(&r2c).unwrap();
        assert_eq!(r2c_shaders.len(), r2c_program.passes.len());
        assert_eq!(r2c_shaders.len(), 4);
        for shader in r2c_shaders {
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }

        let r2r_plan = FftPlan::build(
            FftConfig::new(vec![3, 4])
                .with_transform(crate::TransformKind::Dst(crate::DstType::III)),
        )
        .unwrap();
        let r2r = crate::NdR2rIr::build(&r2r_plan, Direction::Forward, device).unwrap();
        let r2r_program = crate::ProgramIr::nd_r2r(&r2r).unwrap();
        let r2r_shaders = VulkanGlslBackend.lower_nd_r2r(&r2r).unwrap();
        assert_eq!(r2r_shaders.len(), r2r_program.passes.len());
        assert_eq!(r2r_shaders.len(), 10);
        assert!(r2r.axes.iter().all(|axis| {
            axis.transform
                .fft_reduction
                .as_ref()
                .is_some_and(|reduction| reduction.fft_len == axis.pack.axis_len)
        }));
        for shader in r2r_shaders {
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn formatted_nd_real_full_compact_copy_strides_and_mixed_storage_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (Precision::F32, ScalarType::F32, ScalarType::F32),
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let (input_stride, output_stride, input_batch, output_batch) = match transform {
                    crate::TransformKind::RealToComplex => (11usize, 7usize, 33usize, 21usize),
                    crate::TransformKind::ComplexToReal => (7usize, 11usize, 21usize, 33usize),
                    _ => unreachable!(),
                };
                let plan = FftPlan::build(
                    FftConfig::new(vec![3usize, 8])
                        .with_batch_count(2)
                        .with_transform(transform)
                        .with_precision(precision)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        )
                        .with_input_buffer_axis_stride(0, input_stride)
                        .unwrap()
                        .with_output_buffer_axis_stride(0, output_stride)
                        .unwrap(),
                )
                .unwrap();
                let ir = crate::NdRealFftIr::build(&plan, device).unwrap();
                let input_copy = ir.input_formatted_copy.as_ref().unwrap();
                let output_copy = ir.output_formatted_copy.as_ref().unwrap();
                assert_eq!(input_copy.scalar, compute);
                assert_eq!(input_copy.input_storage_scalar, storage);
                assert_eq!(input_copy.output_storage_scalar, compute);
                assert_eq!(input_copy.external_layout.batch_stride, input_batch);
                assert_eq!(output_copy.scalar, compute);
                assert_eq!(output_copy.input_storage_scalar, compute);
                assert_eq!(output_copy.output_storage_scalar, storage);
                assert_eq!(output_copy.external_layout.batch_stride, output_batch);

                let program = crate::ProgramIr::nd_real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_nd_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                let first = &shaders.first().unwrap().glsl;
                let last = &shaders.last().unwrap().glsl;
                assert!(first.contains(&format!("batch * {input_batch}u")));
                assert!(first.contains(&format!("* {input_stride}u")));
                assert!(last.contains(&format!("batch * {output_batch}u")));
                assert!(last.contains(&format!("* {output_stride}u")));
                match (compute, storage) {
                    (ScalarType::F32, ScalarType::F16) => {
                        assert!(first.contains("unpackHalf2x16(vkfft_input.data[external])"));
                        assert!(last.contains("packHalf2x16("));
                    }
                    (ScalarType::F64, ScalarType::F32) => {
                        assert!(first.contains("dvec2((vkfft_input.data[external]).x"));
                        assert!(last.contains("vec2(("));
                    }
                    (ScalarType::F32, ScalarType::F32) => {}
                    _ => unreachable!(),
                }
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn formatted_real_zero_padding_orders_dense_pad_between_copies_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for precision in [Precision::F32, Precision::F64ComputeF32Storage] {
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let (input_stride, output_stride) = match transform {
                    crate::TransformKind::RealToComplex => (11usize, 7usize),
                    crate::TransformKind::ComplexToReal => (7usize, 11usize),
                    _ => unreachable!(),
                };
                let plan = FftPlan::build(
                    FftConfig::new(vec![3usize, 8])
                        .with_batch_count(2)
                        .with_transform(transform)
                        .with_precision(precision)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        )
                        .with_input_buffer_axis_stride(0, input_stride)
                        .unwrap()
                        .with_output_buffer_axis_stride(0, output_stride)
                        .unwrap()
                        .with_zero_padding(0, 1, 2)
                        .unwrap()
                        .with_zero_padding(1, 2, 4)
                        .unwrap(),
                )
                .unwrap();
                let ir = crate::NdRealFftIr::build(&plan, device).unwrap();
                let program = crate::ProgramIr::nd_real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_nd_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert!(
                    shaders
                        .first()
                        .unwrap()
                        .glsl
                        .contains("typed NdFormattedCopyPassIr")
                );
                assert!(
                    shaders
                        .last()
                        .unwrap()
                        .glsl
                        .contains("typed NdFormattedCopyPassIr")
                );
                let zero_pad = if transform == crate::TransformKind::RealToComplex {
                    &shaders[1]
                } else {
                    &shaders[shaders.len() - 2]
                };
                assert!(zero_pad.glsl.contains("typed NdZeroPadPassIr"));
                let pad_ir = ir.zero_pad_pass.as_ref().unwrap();
                assert_eq!(pad_ir.input_storage_scalar, ir.scalar);
                assert_eq!(pad_ir.output_storage_scalar, ir.scalar);
                if precision == Precision::F64ComputeF32Storage {
                    assert!(zero_pad.glsl.contains("dvec2"));
                }
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn formatted_double_double_nd_c2c_wraps_dense_dd_pipeline_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.supports_f64 = true;
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            let plan = FftPlan::build(
                FftConfig::new(vec![3usize, 4])
                    .with_batch_count(2)
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 9)
                    .unwrap(),
            )
            .unwrap();
            let ir =
                crate::DoubleDoubleNdFftIr::build_for_device(&plan, Direction::Forward, device)
                    .unwrap();
            let program = crate::ProgramIr::double_double_nd(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_double_double_nd(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            assert_eq!(
                program.passes.first().unwrap().name,
                "vkfft_dd_nd_gather_formatted_input"
            );
            assert_eq!(
                program.passes.last().unwrap().name,
                "vkfft_dd_nd_scatter_formatted_output"
            );
            let first = &shaders.first().unwrap().glsl;
            let last = &shaders.last().unwrap().glsl;
            assert!(first.contains("batch * 21u"));
            assert!(first.contains("* 7u"));
            assert!(last.contains("batch * 27u"));
            assert!(last.contains("* 9u"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(first.contains("dvec4 data[];"));
                    assert!(last.contains("dvec4 data[];"));
                    assert!(!first.contains("dvec4((vkfft_input.data[external]).x, 0.0"));
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(first.contains("dvec2 data[];"));
                    assert!(first.contains(
                        "dvec4((vkfft_input.data[external]).x, 0.0, (vkfft_input.data[external]).y, 0.0)"
                    ));
                    assert!(last.contains(
                        "dvec2((vkfft_input.data[dense]).x, (vkfft_input.data[dense]).z)"
                    ));
                }
                _ => unreachable!(),
            }
            for shader in shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn formatted_double_double_c2c_and_r2r_zero_padding_stays_on_dense_true_boundary_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.supports_f64 = true;

        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for domain in [ZeroPaddingDomain::Spatial, ZeroPaddingDomain::Frequency] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![3usize, 4])
                        .with_batch_count(2)
                        .with_precision(precision)
                        .with_input_buffer_axis_stride(0, 7)
                        .unwrap()
                        .with_output_buffer_axis_stride(0, 9)
                        .unwrap()
                        .with_zero_padding(0, 1, 2)
                        .unwrap()
                        .with_zero_padding(1, 1, 3)
                        .unwrap()
                        .with_zero_padding_domain(domain),
                )
                .unwrap();
                let ir =
                    crate::DoubleDoubleNdFftIr::build_for_device(&plan, Direction::Forward, device)
                        .unwrap();
                let program = crate::ProgramIr::double_double_nd(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_double_double_nd(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert!(ir.input_formatted_copy.is_some());
                assert!(ir.output_formatted_copy.is_some());
                let zero_shader = match domain {
                    ZeroPaddingDomain::Spatial => &shaders[1].glsl,
                    ZeroPaddingDomain::Frequency => &shaders[shaders.len() - 2].glsl,
                };
                let domain_name = match domain {
                    ZeroPaddingDomain::Spatial => "spatial",
                    ZeroPaddingDomain::Frequency => "frequency",
                };
                assert!(zero_shader.contains(&format!(
                    "fused {domain_name} zero padding at DD ND true boundary"
                )));
                assert!(zero_shader.contains("readonly buffer VkFftInput { dvec4 data[]; }"));
                assert!(zero_shader.contains("buffer VkFftOutput { dvec4 data[]; }"));
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }

            let r2r_plan = FftPlan::build(
                FftConfig::new(vec![3usize, 4])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 9)
                    .unwrap()
                    .with_zero_padding(0, 1, 2)
                    .unwrap()
                    .with_zero_padding(1, 1, 3)
                    .unwrap(),
            )
            .unwrap();
            let r2r_ir =
                crate::DoubleDoubleNdR2rIr::build_for_device(&r2r_plan, Direction::Forward, device)
                    .unwrap();
            let r2r_program = crate::ProgramIr::double_double_nd_r2r(&r2r_ir).unwrap();
            let r2r_shaders = VulkanGlslBackend
                .lower_double_double_nd_r2r(&r2r_ir)
                .unwrap();
            assert_eq!(r2r_shaders.len(), r2r_program.passes.len());
            assert!(r2r_ir.input_formatted_copy.is_some());
            assert!(r2r_ir.output_formatted_copy.is_some());
            let zero_shader = &r2r_shaders[1].glsl;
            assert!(zero_shader.contains("fused spatial zero padding at DD ND R2R true boundary"));
            assert!(zero_shader.contains("readonly buffer VkFftInput { dvec2 data[]; }"));
            assert!(zero_shader.contains("buffer VkFftOutput { dvec2 data[]; }"));
            for shader in r2r_shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn formatted_double_double_real_zero_padding_fuses_into_scalar_copy_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.supports_f64 = true;
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            let r2c_plan = FftPlan::build(
                FftConfig::new(vec![3usize, 8])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::RealToComplex)
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 11)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_zero_padding(0, 1, 2)
                    .unwrap()
                    .with_zero_padding(1, 2, 4)
                    .unwrap(),
            )
            .unwrap();
            let r2c = crate::DoubleDoubleNdRealFftIr::build_for_device(&r2c_plan, device).unwrap();
            let r2c_program = crate::ProgramIr::double_double_nd_real(&r2c).unwrap();
            let r2c_shaders = VulkanGlslBackend.lower_double_double_nd_real(&r2c).unwrap();
            assert_eq!(r2c_shaders.len(), r2c_program.passes.len());
            assert_eq!(
                r2c_program.passes.first().unwrap().name,
                "vkfft_dd_nd_real_gather_formatted_input"
            );
            let r2c_scalar = &r2c_shaders.first().unwrap().glsl;
            assert!(r2c_scalar.contains(
                "fused spatial zero padding at formatted DD ND real scalar true boundary"
            ));
            assert!(r2c_scalar.contains("logical_index / 8u"));
            assert!(r2c_scalar.contains("logical_index / 1u"));
            assert!(r2c_scalar.contains("? dvec2(0.0) :"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(r2c_scalar.contains("readonly buffer VkFftInput { dvec2 data[]; }"));
                    assert!(r2c_scalar.contains("buffer VkFftOutput { dvec2 data[]; }"));
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(r2c_scalar.contains("readonly buffer VkFftInput { double data[]; }"));
                    assert!(r2c_scalar.contains("buffer VkFftOutput { dvec2 data[]; }"));
                    assert!(r2c_scalar.contains("dvec2(vkfft_input.data[external], double(0u))"));
                }
                _ => unreachable!(),
            }

            let c2r_plan = FftPlan::build(
                FftConfig::new(vec![3usize, 8])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::ComplexToReal)
                    .with_inverse_normalization(true)
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 11)
                    .unwrap()
                    .with_zero_padding(0, 1, 2)
                    .unwrap()
                    .with_zero_padding(1, 2, 4)
                    .unwrap(),
            )
            .unwrap();
            let c2r = crate::DoubleDoubleNdRealFftIr::build_for_device(&c2r_plan, device).unwrap();
            let c2r_program = crate::ProgramIr::double_double_nd_real(&c2r).unwrap();
            let c2r_shaders = VulkanGlslBackend.lower_double_double_nd_real(&c2r).unwrap();
            assert_eq!(c2r_shaders.len(), c2r_program.passes.len());
            assert_eq!(
                c2r_program.passes.last().unwrap().name,
                "vkfft_dd_nd_real_scatter_formatted_output"
            );
            let c2r_scalar = &c2r_shaders.last().unwrap().glsl;
            assert!(c2r_scalar.contains(
                "fused spatial zero padding at formatted DD ND real scalar true boundary"
            ));
            assert!(c2r_scalar.contains("logical_index / 8u"));
            assert!(c2r_scalar.contains("logical_index / 1u"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(c2r_scalar.contains("readonly buffer VkFftInput { dvec2 data[]; }"));
                    assert!(c2r_scalar.contains("buffer VkFftOutput { dvec2 data[]; }"));
                    assert!(c2r_scalar.contains("? dvec2(0.0) :"));
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(c2r_scalar.contains("readonly buffer VkFftInput { dvec2 data[]; }"));
                    assert!(c2r_scalar.contains("buffer VkFftOutput { double data[]; }"));
                    assert!(c2r_scalar.contains("? 0.0 :"));
                    assert!(
                        c2r_scalar.contains("(dvec2(vkfft_input.data[dense])).x")
                            || c2r_scalar.contains("(vkfft_input.data[dense]).x")
                    );
                }
                _ => unreachable!(),
            }
            for shader in r2c_shaders.into_iter().chain(c2r_shaders) {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn formatted_double_double_real_and_r2r_copy_strides_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.supports_f64 = true;
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            let real_plan = FftPlan::build(
                FftConfig::new(vec![3usize, 8])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::RealToComplex)
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 11)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 7)
                    .unwrap(),
            )
            .unwrap();
            let real_ir =
                crate::DoubleDoubleNdRealFftIr::build_for_device(&real_plan, device).unwrap();
            let real_program = crate::ProgramIr::double_double_nd_real(&real_ir).unwrap();
            let real_shaders = VulkanGlslBackend
                .lower_double_double_nd_real(&real_ir)
                .unwrap();
            assert_eq!(real_shaders.len(), real_program.passes.len());
            assert_eq!(
                real_program.passes.first().unwrap().name,
                "vkfft_dd_nd_real_gather_formatted_input"
            );
            assert_eq!(
                real_program.passes.last().unwrap().name,
                "vkfft_dd_nd_real_scatter_formatted_output"
            );
            let real_first = &real_shaders.first().unwrap().glsl;
            let real_last = &real_shaders.last().unwrap().glsl;
            assert!(real_first.contains("batch * 33u"));
            assert!(real_first.contains("* 11u"));
            assert!(real_last.contains("batch * 21u"));
            assert!(real_last.contains("* 7u"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(real_first.contains("dvec2 data[];"));
                    assert!(real_last.contains("dvec4 data[];"));
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(real_first.contains("double data[];"));
                    assert!(real_first.contains("dvec2(vkfft_input.data[external], double(0u))"));
                    assert!(real_last.contains(
                        "dvec2((vkfft_input.data[dense]).x, (vkfft_input.data[dense]).z)"
                    ));
                }
                _ => unreachable!(),
            }
            for shader in real_shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }

            let r2r_plan = FftPlan::build(
                FftConfig::new(vec![3usize, 4])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 9)
                    .unwrap(),
            )
            .unwrap();
            let r2r_ir =
                crate::DoubleDoubleNdR2rIr::build_for_device(&r2r_plan, Direction::Forward, device)
                    .unwrap();
            let r2r_program = crate::ProgramIr::double_double_nd_r2r(&r2r_ir).unwrap();
            let r2r_shaders = VulkanGlslBackend
                .lower_double_double_nd_r2r(&r2r_ir)
                .unwrap();
            assert_eq!(r2r_shaders.len(), r2r_program.passes.len());
            assert_eq!(
                r2r_program.passes.first().unwrap().name,
                "vkfft_dd_nd_r2r_gather_formatted_input"
            );
            assert_eq!(
                r2r_program.passes.last().unwrap().name,
                "vkfft_dd_nd_r2r_scatter_formatted_output"
            );
            let r2r_first = &r2r_shaders.first().unwrap().glsl;
            let r2r_last = &r2r_shaders.last().unwrap().glsl;
            assert!(r2r_first.contains("batch * 21u"));
            assert!(r2r_first.contains("* 7u"));
            assert!(r2r_last.contains("batch * 27u"));
            assert!(r2r_last.contains("* 9u"));
            match precision {
                Precision::DoubleDouble => {
                    assert!(r2r_first.contains("dvec2 data[];"));
                    assert!(r2r_last.contains("dvec2 data[];"));
                }
                Precision::DoubleDoubleF64Storage => {
                    assert!(r2r_first.contains("double data[];"));
                    assert!(r2r_first.contains("dvec2(vkfft_input.data[external], double(0u))"));
                    assert!(r2r_last.contains("vkfft_output.data[external] = ("));
                    assert!(r2r_last.contains(").x;"));
                }
                _ => unreachable!(),
            }
            for shader in r2r_shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn formatted_copy_supports_double_double_f64_storage_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        let layout = crate::NdExternalTensorLayout {
            dimensions: vec![3, 4],
            axis_strides: vec![7, 1],
            batch_stride: 21,
        };
        let gather = crate::NdFormattedCopyPassIr::new(
            "vkfft_dd_formatted_gather".to_owned(),
            ScalarType::DoubleDouble,
            ScalarType::F64,
            2,
            layout.clone(),
            crate::NdFormattedCopyOperation::GatherExternalToDense,
            device,
        )
        .unwrap();
        let scatter = crate::NdFormattedCopyPassIr::new(
            "vkfft_dd_formatted_scatter".to_owned(),
            ScalarType::DoubleDouble,
            ScalarType::F64,
            2,
            layout,
            crate::NdFormattedCopyOperation::ScatterDenseToExternal,
            device,
        )
        .unwrap();
        let gather_shader = VulkanGlslBackend
            .lower_nd_formatted_copy_pass(&gather)
            .unwrap();
        let scatter_shader = VulkanGlslBackend
            .lower_nd_formatted_copy_pass(&scatter)
            .unwrap();
        assert!(gather_shader.glsl.contains("dvec2 data[];"));
        assert!(gather_shader.glsl.contains(
            "dvec4((vkfft_input.data[external]).x, 0.0, (vkfft_input.data[external]).y, 0.0)"
        ));
        assert!(scatter_shader.glsl.contains("dvec4 data[];"));
        assert!(
            scatter_shader
                .glsl
                .contains("dvec2((vkfft_input.data[dense]).x, (vkfft_input.data[dense]).z)")
        );
        assert_eq!(gather_shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        assert_eq!(
            scatter_shader.compile_spirv().unwrap().words[0],
            0x0723_0203
        );
    }

    #[test]
    fn formatted_nd_r2r_copy_strides_and_mixed_storage_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (Precision::F32, ScalarType::F32, ScalarType::F32),
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            let plan = FftPlan::build(
                FftConfig::new(vec![3usize, 4])
                    .with_batch_count(2)
                    .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                    .with_precision(precision)
                    .with_input_buffer_axis_stride(0, 7)
                    .unwrap()
                    .with_output_buffer_axis_stride(0, 9)
                    .unwrap(),
            )
            .unwrap();
            let ir = crate::NdR2rIr::build(&plan, Direction::Forward, device).unwrap();
            let input_copy = ir.input_formatted_copy.as_ref().unwrap();
            let output_copy = ir.output_formatted_copy.as_ref().unwrap();
            assert_eq!(input_copy.scalar, compute);
            assert_eq!(input_copy.input_storage_scalar, storage);
            assert_eq!(input_copy.output_storage_scalar, compute);
            assert_eq!(input_copy.external_layout.batch_stride, 21);
            assert_eq!(output_copy.scalar, compute);
            assert_eq!(output_copy.input_storage_scalar, compute);
            assert_eq!(output_copy.output_storage_scalar, storage);
            assert_eq!(output_copy.external_layout.batch_stride, 27);

            let program = crate::ProgramIr::nd_r2r(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_nd_r2r(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let first = &shaders.first().unwrap().glsl;
            let last = &shaders.last().unwrap().glsl;
            assert!(first.contains("batch * 21u"));
            assert!(first.contains("* 7u"));
            assert!(last.contains("batch * 27u"));
            assert!(last.contains("* 9u"));
            match (compute, storage) {
                (ScalarType::F32, ScalarType::F16) => {
                    assert!(first.contains("unpackHalf2x16(vkfft_input.data[external])"));
                    assert!(last.contains("packHalf2x16("));
                }
                (ScalarType::F64, ScalarType::F32) => {
                    assert!(first.contains("dvec2((vkfft_input.data[external]).x"));
                    assert!(last.contains("vec2(("));
                }
                (ScalarType::F32, ScalarType::F32) => {}
                _ => unreachable!(),
            }
            for shader in shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn grouped_multidimensional_real_and_r2r_tail_compile_to_spirv() {
        let batch_count = 5usize;
        let grouped_batch = 3usize;
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;

        let r2c_plan = FftPlan::build(
            FftConfig::new(vec![64, 8])
                .with_batch_count(batch_count)
                .with_precision(Precision::F16StorageF32Compute)
                .with_grouped_batch(0, grouped_batch)
                .unwrap()
                .with_grouped_batch(1, grouped_batch)
                .unwrap()
                .with_transform(crate::TransformKind::RealToComplex)
                .with_zero_padding(0, 1, 2)
                .unwrap()
                .with_zero_padding(1, 2, 4)
                .unwrap(),
        )
        .unwrap();
        let r2c = crate::NdRealFftIr::build(&r2c_plan, device).unwrap();
        let r2c_program = crate::ProgramIr::nd_real_fft(&r2c).unwrap();
        let r2c_shaders = VulkanGlslBackend.lower_nd_real_fft(&r2c).unwrap();
        assert_eq!(r2c_shaders.len(), r2c_program.passes.len());
        assert!(r2c_program.passes.iter().any(|pass| pass.dispatch.x > 2));
        assert!(r2c_shaders.iter().any(|shader| shader.dispatch.x > 2));
        assert!(r2c_shaders.iter().any(|shader| {
            shader.dispatch.x == 2
                && shader.glsl.contains("VKFFT_ZERO_PAD_TENSOR_N")
                && shader.glsl.contains("VKFFT_GROUPED_BATCH = 3u")
                && shader.glsl.contains("batch_end = min")
        }));
        let grouped_nd_passes = r2c_shaders
            .iter()
            .filter(|shader| shader.glsl.contains("VKFFT_LINES"))
            .collect::<Vec<_>>();
        assert_eq!(grouped_nd_passes.len(), 2);
        assert!(grouped_nd_passes.iter().all(|shader| {
            shader.dispatch.x == 2
                && shader.glsl.contains("VKFFT_GROUPED_BATCH = 3u")
                && shader
                    .glsl
                    .contains("for (uint line = 0u; line < VKFFT_LINES; ++line)")
        }));
        assert!(
            r2c_shaders
                .iter()
                .any(|shader| [shader.workgroup_size.x, shader.workgroup_size.y] == [3, 8])
        );
        for (shader, pass) in r2c_shaders.iter().zip(&r2c_program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }

        for (dimensions, transform) in [
            (
                vec![64usize, 4],
                crate::TransformKind::Dct(crate::DctType::II),
            ),
            (
                vec![3usize, 5],
                crate::TransformKind::Dst(crate::DstType::IV),
            ),
        ] {
            let r2r_plan = FftPlan::build(
                FftConfig::new(dimensions)
                    .with_batch_count(batch_count)
                    .with_precision(Precision::F16StorageF32Compute)
                    .with_grouped_batch(0, grouped_batch)
                    .unwrap()
                    .with_grouped_batch(1, grouped_batch)
                    .unwrap()
                    .with_transform(transform),
            )
            .unwrap();
            let r2r = crate::NdR2rIr::build(&r2r_plan, Direction::Forward, device).unwrap();
            let r2r_program = crate::ProgramIr::nd_r2r(&r2r).unwrap();
            let r2r_shaders = VulkanGlslBackend.lower_nd_r2r(&r2r).unwrap();
            assert_eq!(r2r_shaders.len(), r2r_program.passes.len());
            assert!(r2r_program.passes.iter().any(|pass| pass.dispatch.x > 2));
            assert!(r2r_shaders.iter().any(|shader| shader.dispatch.x > 2));
            let grouped_nd_passes = r2r_shaders
                .iter()
                .filter(|shader| shader.glsl.contains("VKFFT_LINES"))
                .collect::<Vec<_>>();
            assert_eq!(grouped_nd_passes.len(), 4);
            assert!(grouped_nd_passes.iter().all(|shader| {
                shader.dispatch.x == 2
                    && shader.glsl.contains("VKFFT_GROUPED_BATCH = 3u")
                    && shader
                        .glsl
                        .contains("for (uint line = 0u; line < VKFFT_LINES; ++line)")
            }));
            for (shader, pass) in r2r_shaders.iter().zip(&r2r_program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn amd_vulkan_f64_compute_f32_storage_keeps_distinct_four_step_threshold() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Amd);
        device.shared_memory_bytes = 64 * 1024;
        device.shared_memory_pow2_bytes = 64 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.coalesced_memory_bytes = 32;
        device.supports_f64 = true;

        for (precision, expected_split, external_scalar) in [
            (
                Precision::F64,
                vec![512usize, 64usize, 8usize],
                ScalarType::F64,
            ),
            (
                Precision::F64ComputeF32Storage,
                vec![512usize, 512usize],
                ScalarType::F32,
            ),
        ] {
            let transform = crate::TransformIr::build(
                FftConfig::new(vec![262_144]).with_precision(precision),
                Direction::Forward,
                device,
            )
            .unwrap();
            let crate::TransformIr::Complex1d(crate::OneDimFftIr::Recursive(recursive)) =
                &transform
            else {
                panic!("AMD Vulkan N262144 threshold witness must remain recursive Stockham");
            };
            assert_eq!(recursive.scalar, ScalarType::F64);
            assert_eq!(recursive.external_scalar, external_scalar);
            assert_eq!(recursive.scheduler_precision, precision);
            let schedule = recursive
                .stockham_upload_schedule
                .as_ref()
                .expect("AMD Vulkan N262144 threshold witness must retain an upload schedule");
            assert_eq!(schedule.axis_split, expected_split);
            assert_eq!(schedule.upload_count, expected_split.len());
            let kernels = recursive
                .four_step_stockham_upload_kernels()
                .unwrap()
                .expect("AMD Vulkan N262144 threshold witness must materialize Four-step kernels");
            assert_eq!(kernels.len(), expected_split.len());

            let program = crate::ProgramIr::recursive_fft(recursive).unwrap();
            program.validate().unwrap();
            assert_eq!(program.scalar, ScalarType::F64);
            assert_eq!(program.input_resource().unwrap().scalar, external_scalar);
            assert_eq!(program.output_resource().unwrap().scalar, external_scalar);
            let shaders = VulkanGlslBackend.lower_recursive_fft(recursive).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            for shader in shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn multidimensional_real_mixed_storage_keeps_compact_tensor_in_compute_precision() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.supports_f64 = true;
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for last_axis in [7usize, 8] {
                for transform in [
                    crate::TransformKind::RealToComplex,
                    crate::TransformKind::ComplexToReal,
                ] {
                    let config = FftConfig::new(vec![3, last_axis])
                        .with_precision(precision)
                        .with_transform(transform)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        );
                    let plan = FftPlan::build(config).unwrap();
                    let ir = crate::NdRealFftIr::build(&plan, device).unwrap();
                    assert_eq!(ir.scalar, compute);
                    assert_eq!(ir.external_scalar, storage);
                    assert_eq!(ir.real_axis.scalar, compute);
                    assert_eq!(ir.real_axis.transform.external_storage_scalar(), compute);
                    assert!(ir.complex_axes.iter().all(|axis| {
                        axis.transform.scalar() == compute
                            && axis.transform.external_storage_scalar() == compute
                    }));
                    match ir.kind {
                        crate::RealFftKind::RealToComplex => {
                            assert_eq!(ir.real_axis.input_storage_scalar(), storage);
                            assert_eq!(ir.real_axis.output_storage_scalar(), compute);
                            assert_eq!(ir.complex_axes[0].pack.input_storage_scalar, compute);
                            assert_eq!(
                                ir.complex_axes
                                    .last()
                                    .unwrap()
                                    .scatter
                                    .output_storage_scalar,
                                storage
                            );
                        }
                        crate::RealFftKind::ComplexToReal => {
                            assert_eq!(ir.complex_axes[0].pack.input_storage_scalar, storage);
                            assert_eq!(
                                ir.complex_axes
                                    .last()
                                    .unwrap()
                                    .scatter
                                    .output_storage_scalar,
                                compute
                            );
                            assert_eq!(ir.real_axis.input_storage_scalar(), compute);
                            assert_eq!(ir.real_axis.output_storage_scalar(), storage);
                        }
                    }
                    let program = crate::ProgramIr::nd_real_fft(&ir).unwrap();
                    assert_eq!(program.input_resource().unwrap().scalar, storage);
                    assert_eq!(program.output_resource().unwrap().scalar, storage);
                    assert!(program.resources.iter().all(|resource| {
                        matches!(
                            resource.kind,
                            crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                        ) || resource.scalar == compute
                    }));
                    let shaders = VulkanGlslBackend.lower_nd_real_fft(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }
            }

            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let config = FftConfig::new(vec![3, 8])
                    .with_precision(precision)
                    .with_transform(transform)
                    .with_inverse_normalization(transform == crate::TransformKind::ComplexToReal)
                    .with_zero_padding(1, 6, 8)
                    .unwrap();
                let plan = FftPlan::build(config).unwrap();
                let ir = crate::NdRealFftIr::build(&plan, device).unwrap();
                let zero = ir.zero_pad_pass.as_ref().unwrap();
                match ir.kind {
                    crate::RealFftKind::RealToComplex => {
                        assert_eq!(
                            (zero.input_storage_scalar, zero.output_storage_scalar),
                            (storage, compute)
                        );
                        assert_eq!(ir.real_axis.input_storage_scalar(), compute);
                        assert_eq!(ir.real_axis.output_storage_scalar(), compute);
                        assert_eq!(
                            ir.complex_axes
                                .last()
                                .unwrap()
                                .scatter
                                .output_storage_scalar,
                            storage
                        );
                    }
                    crate::RealFftKind::ComplexToReal => {
                        assert_eq!(
                            (zero.input_storage_scalar, zero.output_storage_scalar),
                            (compute, storage)
                        );
                        assert_eq!(ir.complex_axes[0].pack.input_storage_scalar, storage);
                        assert_eq!(ir.real_axis.input_storage_scalar(), compute);
                        assert_eq!(ir.real_axis.output_storage_scalar(), compute);
                    }
                }
                let program = crate::ProgramIr::nd_real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_nd_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn r2r_mixed_storage_covers_fft_reduction_direct_and_nd() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (
                crate::Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                crate::Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for direction in [Direction::Forward, Direction::Inverse] {
                for transform in [
                    crate::TransformKind::Dct(crate::DctType::I),
                    crate::TransformKind::Dst(crate::DstType::I),
                    crate::TransformKind::Dct(crate::DctType::II),
                    crate::TransformKind::Dst(crate::DstType::III),
                ] {
                    let plan = FftPlan::build(
                        FftConfig::new(vec![9])
                            .with_batch_count(2)
                            .with_precision(precision)
                            .with_transform(transform)
                            .with_inverse_normalization(direction == Direction::Inverse),
                    )
                    .unwrap();
                    let ir = crate::R2rIr::build(&plan, direction, device).unwrap();
                    assert_eq!(ir.scalar, compute);
                    assert_eq!(ir.external_scalar, storage);
                    let reduction = ir.fft_reduction.as_ref().unwrap();
                    assert_eq!(reduction.scalar, compute);
                    assert_eq!(reduction.external_scalar, storage);
                    assert_eq!(reduction.fft.scalar(), compute);
                    assert_eq!(reduction.fft.external_storage_scalar(), compute);
                    assert_eq!(reduction.preprocess.input_storage_scalar, storage);
                    assert_eq!(reduction.preprocess.output_storage_scalar, compute);
                    assert_eq!(reduction.postprocess.input_storage_scalar, compute);
                    assert_eq!(reduction.postprocess.output_storage_scalar, storage);
                    if matches!(
                        transform,
                        crate::TransformKind::Dct(crate::DctType::II)
                            | crate::TransformKind::Dst(crate::DstType::III)
                    ) {
                        assert_eq!(reduction.fft_len, 9);
                    }
                    let program = crate::ProgramIr::r2r(&ir).unwrap();
                    assert_eq!(program.input_resource().unwrap().scalar, storage);
                    assert_eq!(program.output_resource().unwrap().scalar, storage);
                    assert!(program.resources.iter().all(|resource| {
                        matches!(
                            resource.kind,
                            crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                        ) || resource.scalar == compute
                    }));
                    let shaders = VulkanGlslBackend.lower_r2r_program(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }

                for transform in [
                    crate::TransformKind::Dct(crate::DctType::I),
                    crate::TransformKind::Dst(crate::DstType::I),
                    crate::TransformKind::Dct(crate::DctType::II),
                    crate::TransformKind::Dst(crate::DstType::III),
                ] {
                    let plan = FftPlan::build(
                        FftConfig::new(vec![3, 4])
                            .with_precision(precision)
                            .with_transform(transform)
                            .with_inverse_normalization(direction == Direction::Inverse),
                    )
                    .unwrap();
                    let ir = crate::NdR2rIr::build(&plan, direction, device).unwrap();
                    assert_eq!(ir.scalar, compute);
                    assert_eq!(ir.external_scalar, storage);
                    assert!(ir.axes.iter().all(|axis| {
                        axis.transform.scalar == compute
                            && axis.transform.external_scalar == compute
                    }));
                    assert_eq!(ir.axes[0].pack.input_storage_scalar, storage);
                    assert_eq!(ir.axes[0].pack.output_storage_scalar, compute);
                    assert_eq!(
                        ir.axes.last().unwrap().scatter.input_storage_scalar,
                        compute
                    );
                    assert_eq!(
                        ir.axes.last().unwrap().scatter.output_storage_scalar,
                        storage
                    );
                    let program = crate::ProgramIr::nd_r2r(&ir).unwrap();
                    assert_eq!(program.input_resource().unwrap().scalar, storage);
                    assert_eq!(program.output_resource().unwrap().scalar, storage);
                    assert!(program.resources.iter().all(|resource| {
                        matches!(
                            resource.kind,
                            crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                        ) || resource.scalar == compute
                    }));
                    let shaders = VulkanGlslBackend.lower_nd_r2r(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }
            }
        }
    }

    #[test]
    fn even_iv_mixed_storage_and_nd_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (
                crate::Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                crate::Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for direction in [Direction::Forward, Direction::Inverse] {
                for transform in [
                    crate::TransformKind::Dct(crate::DctType::IV),
                    crate::TransformKind::Dst(crate::DstType::IV),
                ] {
                    let plan = FftPlan::build(
                        FftConfig::new(vec![8])
                            .with_batch_count(2)
                            .with_precision(precision)
                            .with_transform(transform)
                            .with_inverse_normalization(direction == Direction::Inverse),
                    )
                    .unwrap();
                    let ir = crate::R2rIr::build(&plan, direction, device).unwrap();
                    let reduction = ir.fft_reduction.as_ref().unwrap();
                    assert_eq!(reduction.fft_len, 4);
                    assert_eq!(reduction.scalar, compute);
                    assert_eq!(reduction.external_scalar, storage);
                    assert_eq!(reduction.preprocess.input_storage_scalar, storage);
                    assert_eq!(reduction.preprocess.output_storage_scalar, compute);
                    assert_eq!(reduction.postprocess.input_storage_scalar, compute);
                    assert_eq!(reduction.postprocess.output_storage_scalar, storage);
                    let program = crate::ProgramIr::r2r(&ir).unwrap();
                    assert_eq!(program.input_resource().unwrap().scalar, storage);
                    assert_eq!(program.output_resource().unwrap().scalar, storage);
                    let shaders = VulkanGlslBackend.lower_r2r_program(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }

                    let nd_plan = FftPlan::build(
                        FftConfig::new(vec![4, 8])
                            .with_precision(precision)
                            .with_transform(transform)
                            .with_inverse_normalization(direction == Direction::Inverse),
                    )
                    .unwrap();
                    let nd = crate::NdR2rIr::build(&nd_plan, direction, device).unwrap();
                    assert!(nd.axes.iter().all(|axis| {
                        axis.transform
                            .fft_reduction
                            .as_ref()
                            .is_some_and(|reduction| reduction.fft_len == axis.pack.axis_len / 2)
                    }));
                    let nd_program = crate::ProgramIr::nd_r2r(&nd).unwrap();
                    assert_eq!(nd_program.input_resource().unwrap().scalar, storage);
                    assert_eq!(nd_program.output_resource().unwrap().scalar, storage);
                    let nd_shaders = VulkanGlslBackend.lower_nd_r2r(&nd).unwrap();
                    assert_eq!(nd_shaders.len(), nd_program.passes.len());
                    for shader in nd_shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }
            }
        }
    }

    #[test]
    fn r2r_fft_reduction_programs_compile_f32_f64() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for precision in [crate::Precision::F32, crate::Precision::F64] {
            for (transform, length, expected_fft_len) in [
                (
                    crate::TransformKind::Dct(crate::DctType::I),
                    9usize,
                    16usize,
                ),
                (
                    crate::TransformKind::Dst(crate::DstType::I),
                    9usize,
                    20usize,
                ),
                (
                    crate::TransformKind::Dct(crate::DctType::II),
                    9usize,
                    9usize,
                ),
                (
                    crate::TransformKind::Dct(crate::DctType::III),
                    9usize,
                    9usize,
                ),
                (
                    crate::TransformKind::Dst(crate::DstType::II),
                    9usize,
                    9usize,
                ),
                (
                    crate::TransformKind::Dst(crate::DstType::III),
                    9usize,
                    9usize,
                ),
                (
                    crate::TransformKind::Dct(crate::DctType::IV),
                    8usize,
                    4usize,
                ),
                (
                    crate::TransformKind::Dst(crate::DstType::IV),
                    8usize,
                    4usize,
                ),
            ] {
                for direction in [Direction::Forward, Direction::Inverse] {
                    let plan = FftPlan::build(
                        FftConfig::new(vec![length])
                            .with_batch_count(2)
                            .with_precision(precision)
                            .with_transform(transform)
                            .with_inverse_normalization(direction == Direction::Inverse),
                    )
                    .unwrap();
                    let ir = crate::R2rIr::build(&plan, direction, device).unwrap();
                    let reduction = ir.fft_reduction.as_ref().unwrap();
                    assert_eq!(reduction.fft_len, expected_fft_len);
                    let expected_direction = match ir.effective_transform {
                        crate::R2rTransform::Dct(crate::DctType::I)
                        | crate::R2rTransform::Dst(crate::DstType::I)
                        | crate::R2rTransform::Dct(crate::DctType::II)
                        | crate::R2rTransform::Dst(crate::DstType::II) => Direction::Forward,
                        _ => Direction::Inverse,
                    };
                    assert_eq!(reduction.fft.direction(), expected_direction);
                    let program = crate::ProgramIr::r2r(&ir).unwrap();
                    let shaders = VulkanGlslBackend.lower_r2r_program(&ir).unwrap();
                    assert_eq!(shaders.len(), program.passes.len());
                    assert!(shaders.first().unwrap().glsl.contains("VKFFT_FFT_N"));
                    assert!(shaders.last().unwrap().glsl.contains("VKFFT_SCALE"));
                    for shader in shaders {
                        assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                    }
                }
            }
        }
    }

    #[test]
    fn grouped_r2r_fft_and_direct_tail_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        for (length, transform) in [
            (9usize, crate::TransformKind::Dct(crate::DctType::I)),
            (9usize, crate::TransformKind::Dst(crate::DstType::III)),
            (8usize, crate::TransformKind::Dct(crate::DctType::IV)),
            (9usize, crate::TransformKind::Dst(crate::DstType::IV)),
        ] {
            for direction in [Direction::Forward, Direction::Inverse] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![length])
                        .with_batch_count(5)
                        .with_grouped_batch(0, 3)
                        .unwrap()
                        .with_precision(crate::Precision::F16StorageF32Compute)
                        .with_transform(transform)
                        .with_inverse_normalization(direction == Direction::Inverse),
                )
                .unwrap();
                let ir = crate::R2rIr::build(&plan, direction, device).unwrap();
                assert_eq!(ir.grouped_batch, 3);
                assert_eq!(ir.dispatch.x, 2);
                let program = crate::ProgramIr::r2r(&ir).unwrap();
                assert!(program.passes.iter().all(|pass| pass.dispatch.x == 2));
                let shaders = VulkanGlslBackend.lower_r2r_program(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                if ir.fft_reduction.is_some() {
                    assert!(
                        shaders
                            .first()
                            .unwrap()
                            .glsl
                            .contains("VKFFT_GROUPED_BATCH = 3u")
                    );
                    assert!(
                        shaders
                            .last()
                            .unwrap()
                            .glsl
                            .contains("VKFFT_GROUPED_BATCH = 3u")
                    );
                } else {
                    assert_eq!(shaders.len(), 1);
                    assert!(shaders[0].glsl.contains("VKFFT_GROUPED_BATCH = 3u"));
                    assert!(shaders[0].glsl.contains("batch_end = min"));
                }
                for (shader, pass) in shaders.iter().zip(&program.passes) {
                    assert_eq!(shader.dispatch, pass.dispatch);
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn odd_r2r_iv_two_n_reductions_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        for transform in [
            crate::TransformKind::Dct(crate::DctType::IV),
            crate::TransformKind::Dst(crate::DstType::IV),
        ] {
            let plan = FftPlan::build(
                FftConfig::new(vec![9])
                    .with_batch_count(2)
                    .with_transform(transform),
            )
            .unwrap();
            let ir = crate::R2rIr::build(&plan, Direction::Forward, device).unwrap();
            let reduction = ir
                .fft_reduction
                .as_deref()
                .expect("odd DCT/DST-IV must use the 2N FFT reduction");
            assert_eq!(reduction.fft_len, 18);
            assert_eq!(reduction.fft.direction(), Direction::Forward);
            let program = crate::ProgramIr::r2r(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_r2r_program(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            assert!(shaders[0].glsl.contains("2.0 * float(VKFFT_N)"));
            assert!(
                shaders
                    .last()
                    .unwrap()
                    .glsl
                    .contains("4.0 * float(VKFFT_N)")
            );
            for (shader, pass) in shaders.iter().zip(&program.passes) {
                assert_eq!(shader.dispatch, pass.dispatch);
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn generic_one_dim_bluestein_lowers_in_program_order() {
        let mut bluestein_tuning = crate::PlannerTuning::portable();
        bluestein_tuning.max_rader_fft_prime = 100;
        let plan = FftPlan::build(
            FftConfig::new(vec![103])
                .with_batch_count(2)
                .with_tuning(bluestein_tuning),
        )
        .unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::OneDimFftIr::build(&plan, Direction::Forward, device).unwrap();
        let program = crate::ProgramIr::one_dim_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_one_dim_fft(&ir).unwrap();
        assert_eq!(shaders.len(), program.passes.len());
        assert_eq!(shaders.len(), 4);
        assert_eq!(shaders[2].descriptors.len(), 3);
        assert_eq!(shaders[2].descriptors[2].role, BufferRole::LookupTable);
        assert!(shaders[2].glsl.contains("vkfft_lut.data["));
        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn even_real_fft_half_size_passes_lower_for_f32_and_f64() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        for precision in [crate::Precision::F32, crate::Precision::F64] {
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![30])
                        .with_batch_count(2)
                        .with_precision(precision)
                        .with_transform(transform)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        ),
                )
                .unwrap();
                let ir = crate::RealFftIr::build(&plan, device).unwrap();
                assert_eq!(ir.algorithm, crate::RealFftAlgorithm::EvenHalfSize);
                assert_eq!(ir.transform_len(), 15);
                let fused = ir
                    .fused_even_input_stockham_kernel()
                    .unwrap()
                    .expect("30-point even-real transform should fuse around one Stockham root");
                let program = crate::ProgramIr::real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                match transform {
                    crate::TransformKind::RealToComplex => {
                        assert_eq!(shaders.len(), 1);
                        assert!(matches!(
                            fused.io_mapping,
                            StockhamIoMapping::RealEvenPack(_)
                        ));
                        assert!(matches!(
                            fused.output_modifier,
                            StockhamOutputModifier::RealEvenPostprocess(_)
                        ));
                        assert!(shaders[0].glsl.contains("VKFFT_REAL_FULL_N"));
                        assert!(shaders[0].glsl.contains("vkfft_real_minus_i_rotated"));
                        assert!(shaders[0].glsl.contains("barrier();"));
                        assert!(shaders[0].descriptors.iter().any(|descriptor| {
                            descriptor.role == BufferRole::Auxiliary
                                && descriptor.access == BufferAccess::ReadWrite
                        }));
                    }
                    crate::TransformKind::ComplexToReal => {
                        assert_eq!(shaders.len(), 1);
                        assert!(matches!(
                            fused.io_mapping,
                            StockhamIoMapping::RealEvenInversePreprocess(_)
                        ));
                        assert!(matches!(
                            fused.output_modifier,
                            StockhamOutputModifier::RealEvenUnpack(_)
                        ));
                        assert!(shaders[0].glsl.contains("VKFFT_REAL_COMPACT_N"));
                    }
                    _ => unreachable!(),
                }
                for shader in shaders {
                    let spirv = shader.compile_spirv().unwrap();
                    assert_eq!(spirv.words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn recursive_even_real_boundaries_lower_and_compile_to_spirv() {
        let length = 578usize;
        for scalar in [crate::Precision::F32, crate::Precision::F64] {
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.shared_memory_bytes = 128 * 1024;
            device.shared_memory_pow2_bytes = 128 * 1024;
            device.supports_f64 = true;
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![length])
                        .with_precision(scalar)
                        .with_transform(transform)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        ),
                )
                .unwrap();
                let ir = crate::RealFftIr::build(&plan, device).unwrap();
                assert!(ir.fused_even_recursive_ir().unwrap().is_some());
                let program = crate::ProgramIr::real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert!(shaders[0].glsl.contains("vkfft_real_input_base"));
                if transform == crate::TransformKind::ComplexToReal {
                    assert!(shaders[0].glsl.contains("VKFFT_REAL_COMPACT_N"));
                    assert!(shaders.last().unwrap().glsl.contains("VKFFT_REAL_OUTPUT_N"));
                } else {
                    assert!(shaders[0].glsl.contains("VKFFT_REAL_FULL_N"));
                    let scatter = &shaders.last().unwrap().glsl;
                    assert!(scatter.contains("VKFFT_REAL_OUTPUT_N"));
                    assert!(scatter.contains("mirror_source"));
                    assert!(scatter.contains("vkfft_real_a.x + vkfft_real_b.x"));
                    assert!(!scatter.contains("postprocess_even_half"));
                }
                for shader in shaders {
                    let spirv = shader.compile_spirv().unwrap();
                    assert_eq!(spirv.words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn bluestein_even_real_boundaries_lower_and_compile_to_spirv() {
        let length = 206usize;
        for precision in [crate::Precision::F32, crate::Precision::F64] {
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.shared_memory_bytes = 128 * 1024;
            device.shared_memory_pow2_bytes = 128 * 1024;
            device.supports_f64 = true;
            let mut tuning = crate::PlannerTuning::portable();
            tuning.max_rader_fft_prime = 100;
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![length])
                        .with_precision(precision)
                        .with_transform(transform)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        )
                        .with_tuning(tuning),
                )
                .unwrap();
                let ir = crate::RealFftIr::build(&plan, device).unwrap();
                assert!(ir.fused_even_bluestein_ir().unwrap().is_some());
                let program = crate::ProgramIr::real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert!(program.passes.iter().all(|pass| {
                    !pass.name.contains("pack_even_odd")
                        && !pass.name.contains("preprocess_even_half")
                        && !pass.name.contains("postprocess_even_half")
                        && !pass.name.contains("unpack_even_odd")
                }));
                match transform {
                    crate::TransformKind::RealToComplex => {
                        let preprocess = &shaders.first().unwrap().glsl;
                        let postprocess = &shaders.last().unwrap().glsl;
                        assert!(preprocess.contains("VKFFT_REAL_FULL_N = 206u"));
                        assert!(preprocess.contains("input_base + 2u * i + 1u"));
                        assert!(postprocess.contains("mirror_i = VKFFT_N - i"));
                        assert!(postprocess.contains("vkfft_real_rotated.y"));
                        assert!(postprocess.contains("output_base + VKFFT_N"));
                    }
                    crate::TransformKind::ComplexToReal => {
                        let preprocess = &shaders.first().unwrap().glsl;
                        let postprocess = &shaders.last().unwrap().glsl;
                        assert!(preprocess.contains("VKFFT_INPUT_STRIDE = 104u"));
                        assert!(
                            preprocess.contains("VKFFT_TAU")
                                || preprocess.contains("vkfft_tau_f64()")
                        );
                        assert!(preprocess.contains("VKFFT_REAL_FULL_N = 206u"));
                        assert!(preprocess.contains("vkfft_real_mirror"));
                        assert!(preprocess.contains("vkfft_real_rotated"));
                        assert!(postprocess.contains("VKFFT_OUTPUT_STRIDE = 206u"));
                        assert!(postprocess.contains("output_base + 2u * i + 1u"));
                    }
                    _ => unreachable!(),
                }
                for shader in shaders {
                    let spirv = shader.compile_spirv().unwrap();
                    assert_eq!(spirv.words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn bluestein_even_real_recursive_convolution_lowers_to_spirv() {
        let length = 4106usize;
        let mut tuning = crate::PlannerTuning::portable();
        tuning.max_rader_fft_prime = 100;
        for precision in [crate::Precision::F32, crate::Precision::F64] {
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.shared_memory_bytes = 32 * 1024;
            device.shared_memory_pow2_bytes = 32 * 1024;
            device.supports_f64 = true;
            for transform in [
                crate::TransformKind::RealToComplex,
                crate::TransformKind::ComplexToReal,
            ] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![length])
                        .with_precision(precision)
                        .with_transform(transform)
                        .with_inverse_normalization(
                            transform == crate::TransformKind::ComplexToReal,
                        )
                        .with_tuning(tuning),
                )
                .unwrap();
                let ir = crate::RealFftIr::build(&plan, device).unwrap();
                let fused = ir.fused_even_bluestein_ir().unwrap().unwrap();
                assert_eq!(fused.logical_len, 2053);
                assert_eq!(fused.convolution_len, 4368);
                assert!(matches!(
                    fused.forward_fft.root,
                    crate::RecursiveFftNodeIr::CooleyTukey(_)
                ));
                assert!(matches!(
                    fused.inverse_fft.root,
                    crate::RecursiveFftNodeIr::CooleyTukey(_)
                ));
                let program = crate::ProgramIr::real_fft(&ir).unwrap();
                let shaders = VulkanGlslBackend.lower_real_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                assert!(program.passes.len() > 6);
                assert!(program.passes.iter().all(|pass| {
                    !pass.name.contains("pack_even_odd")
                        && !pass.name.contains("preprocess_even_half")
                        && !pass.name.contains("postprocess_even_half")
                        && !pass.name.contains("unpack_even_odd")
                }));
                for shader in shaders {
                    let spirv = shader.compile_spirv().unwrap();
                    assert_eq!(spirv.words[0], 0x0723_0203);
                }
            }
        }
    }

