    #[test]
    fn multidimensional_axes_lower_in_program_order_and_compile_to_spirv() {
        let plan = FftPlan::build(FftConfig::new(vec![3, 4]).with_batch_count(2)).unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::NdFftIr::build(&plan, Direction::Forward, device).unwrap();
        let program = crate::ProgramIr::nd_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
        assert_eq!(shaders.len(), 6);
        assert_eq!(shaders.len(), program.passes.len());
        assert!(
            shaders[0]
                .glsl
                .contains("uint natural_local = outer * VKFFT_AXIS")
        );
        for (shader, pass) in shaders.iter().zip(&program.passes) {
            assert_eq!(shader.dispatch, pass.dispatch);
            assert_eq!(shader.descriptors.len(), pass.bindings.len());
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
    }

    #[test]
    fn multidimensional_formatted_batch_stride_lowers_boundary_addresses_to_spirv() {
        let plan = FftPlan::build(
            FftConfig::new(vec![3, 4])
                .with_batch_count(2)
                .with_input_buffer_batch_stride(17)
                .with_output_buffer_batch_stride(19),
        )
        .unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::NdFftIr::build(&plan, Direction::Forward, device).unwrap();
        let program = crate::ProgramIr::nd_fft(&ir).unwrap();
        let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
        assert_eq!(shaders.len(), 6);
        assert_eq!(shaders.len(), program.passes.len());
        assert!(shaders[0].glsl.contains("VKFFT_INPUT_BATCH_STRIDE = 17u"));
        assert!(shaders[0].glsl.contains("VKFFT_OUTPUT_BATCH_STRIDE = 12u"));
        assert!(
            shaders[0]
                .glsl
                .contains("batch * VKFFT_INPUT_BATCH_STRIDE + natural_local")
        );
        assert!(shaders[5].glsl.contains("VKFFT_INPUT_BATCH_STRIDE = 12u"));
        assert!(shaders[5].glsl.contains("VKFFT_OUTPUT_BATCH_STRIDE = 19u"));
        assert!(
            shaders[5]
                .glsl
                .contains("batch * VKFFT_OUTPUT_BATCH_STRIDE + natural_local")
        );
        for shader in shaders {
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn multidimensional_formatted_tensor_strides_lower_row_plane_addresses_to_spirv() {
        let plan = FftPlan::build(
            FftConfig::new(vec![2, 3, 4])
                .with_batch_count(2)
                .with_input_buffer_axis_stride(1, 6)
                .unwrap()
                .with_input_buffer_axis_stride(0, 20)
                .unwrap()
                .with_output_buffer_axis_stride(1, 7)
                .unwrap()
                .with_output_buffer_axis_stride(0, 24)
                .unwrap(),
        )
        .unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::NdFftIr::build(&plan, Direction::Forward, device).unwrap();
        let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
        let first = &shaders[0].glsl;
        let last = &shaders.last().unwrap().glsl;
        assert!(first.contains("batch * 40u"));
        assert!(first.contains("((natural_local / 12u) % 2u) * 20u"));
        assert!(first.contains("((natural_local / 4u) % 3u) * 6u"));
        assert!(first.contains("(natural_local % 4u)"));
        assert!(last.contains("batch * 48u"));
        assert!(last.contains("((natural_local / 12u) % 2u) * 24u"));
        assert!(last.contains("((natural_local / 4u) % 3u) * 7u"));
        for shader in shaders {
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn multidimensional_mixed_storage_touches_only_first_pack_and_last_scatter() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for direction in [Direction::Forward, Direction::Inverse] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![3, 4])
                        .with_batch_count(2)
                        .with_precision(precision)
                        .with_inverse_normalization(direction == Direction::Inverse)
                        .with_input_buffer_axis_stride(0, 7)
                        .unwrap()
                        .with_output_buffer_axis_stride(0, 9)
                        .unwrap()
                        .with_input_buffer_batch_stride(23)
                        .with_output_buffer_batch_stride(29),
                )
                .unwrap();
                let ir = crate::NdFftIr::build(&plan, direction, device).unwrap();
                assert_eq!(ir.scalar, compute);
                assert_eq!(ir.external_scalar, storage);
                assert_eq!(ir.axes[0].pack.input_storage_scalar, storage);
                assert_eq!(ir.axes[0].pack.output_storage_scalar, compute);
                assert_eq!(ir.axes[1].scatter.input_storage_scalar, compute);
                assert_eq!(ir.axes[1].scatter.output_storage_scalar, storage);
                assert!(ir.axes.iter().all(|axis| {
                    axis.transform.scalar() == compute
                        && axis.transform.external_storage_scalar() == compute
                }));
                assert!(ir.axes[0].scatter.input_storage_scalar == compute);
                assert!(ir.axes[0].scatter.output_storage_scalar == compute);
                assert!(ir.axes[1].pack.input_storage_scalar == compute);
                assert!(ir.axes[1].pack.output_storage_scalar == compute);
                assert_eq!(ir.axes[0].pack.input_batch_stride, 23);
                assert_eq!(ir.axes[1].scatter.output_batch_stride, 29);
                assert_eq!(
                    ir.axes[0]
                        .pack
                        .input_external_layout
                        .as_ref()
                        .unwrap()
                        .axis_strides,
                    vec![7, 1]
                );
                assert_eq!(
                    ir.axes[1]
                        .scatter
                        .output_external_layout
                        .as_ref()
                        .unwrap()
                        .axis_strides,
                    vec![9, 1]
                );

                let program = crate::ProgramIr::nd_fft(&ir).unwrap();
                assert_eq!(program.input_resource().unwrap().scalar, storage);
                assert_eq!(program.output_resource().unwrap().scalar, storage);
                assert_eq!(
                    program
                        .input_resource()
                        .unwrap()
                        .external_layout
                        .unwrap()
                        .physical_stride,
                    23
                );
                assert_eq!(
                    program
                        .output_resource()
                        .unwrap()
                        .external_layout
                        .unwrap()
                        .physical_stride,
                    29
                );
                assert!(program.resources.iter().all(|resource| {
                    matches!(
                        resource.kind,
                        crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                    ) || resource.scalar == compute
                }));

                let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
                assert_eq!(shaders.len(), 6);
                assert_eq!(shaders.len(), program.passes.len());
                assert!(shaders[0].glsl.contains("batch * 23u"));
                assert!(shaders[0].glsl.contains("* 7u"));
                assert!(shaders[5].glsl.contains("batch * 29u"));
                assert!(shaders[5].glsl.contains("* 9u"));
                match (compute, storage) {
                    (ScalarType::F32, ScalarType::F16) => {
                        assert!(
                            shaders[0]
                                .glsl
                                .contains("readonly buffer VkFftInput { uint data[]; }")
                        );
                        assert!(
                            shaders[0]
                                .glsl
                                .contains("unpackHalf2x16(vkfft_input.data[input_natural])")
                        );
                        assert!(
                            shaders[5]
                                .glsl
                                .contains("buffer VkFftOutput { uint data[]; }")
                        );
                        assert!(shaders[5].glsl.contains("packHalf2x16("));
                    }
                    (ScalarType::F64, ScalarType::F32) => {
                        assert!(
                            shaders[0]
                                .glsl
                                .contains("readonly buffer VkFftInput { vec2 data[]; }")
                        );
                        assert!(
                            shaders[0]
                                .glsl
                                .contains("dvec2((vkfft_input.data[input_natural]).x")
                        );
                        assert!(
                            shaders[5]
                                .glsl
                                .contains("buffer VkFftOutput { vec2 data[]; }")
                        );
                        assert!(shaders[5].glsl.contains("= vec2("));
                    }
                    _ => unreachable!(),
                }
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn multidimensional_zero_padding_mixed_storage_is_directional_and_compiles_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            for direction in [Direction::Forward, Direction::Inverse] {
                let config = FftConfig::new(vec![3, 4])
                    .with_batch_count(2)
                    .with_precision(precision)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(1, 2, 4)
                    .unwrap();
                let plan = FftPlan::build(config).unwrap();
                let ir = crate::NdFftIr::build(&plan, direction, device).unwrap();
                let zero = ir.zero_pad_pass.as_ref().unwrap();
                assert_eq!(zero.scalar, compute);
                match direction {
                    Direction::Forward => {
                        assert_eq!(zero.input_storage_scalar, storage);
                        assert_eq!(zero.output_storage_scalar, compute);
                        assert_eq!(ir.axes[0].pack.input_storage_scalar, compute);
                        assert_eq!(ir.axes[1].scatter.output_storage_scalar, storage);
                    }
                    Direction::Inverse => {
                        assert_eq!(zero.input_storage_scalar, compute);
                        assert_eq!(zero.output_storage_scalar, storage);
                        assert_eq!(ir.axes[0].pack.input_storage_scalar, storage);
                        assert_eq!(ir.axes[1].scatter.output_storage_scalar, compute);
                    }
                }
                assert!(ir.axes.iter().all(|axis| {
                    axis.transform.scalar() == compute
                        && axis.transform.external_storage_scalar() == compute
                }));

                let program = crate::ProgramIr::nd_fft(&ir).unwrap();
                assert_eq!(program.input_resource().unwrap().scalar, storage);
                assert_eq!(program.output_resource().unwrap().scalar, storage);
                assert!(program.resources.iter().all(|resource| {
                    matches!(
                        resource.kind,
                        crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                    ) || resource.scalar == compute
                }));
                let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
                assert_eq!(shaders.len(), program.passes.len());
                let zero_shader = match direction {
                    Direction::Forward => shaders.first().unwrap(),
                    Direction::Inverse => shaders.last().unwrap(),
                };
                match (direction, compute, storage) {
                    (Direction::Forward, ScalarType::F32, ScalarType::F16) => {
                        assert!(
                            zero_shader
                                .glsl
                                .contains("readonly buffer VkFftInput { uint data[]; }")
                        );
                        assert!(
                            zero_shader
                                .glsl
                                .contains("buffer VkFftOutput { vec2 data[]; }")
                        );
                        assert!(zero_shader.glsl.contains("unpackHalf2x16(vkfft_input.data"));
                    }
                    (Direction::Inverse, ScalarType::F32, ScalarType::F16) => {
                        assert!(
                            zero_shader
                                .glsl
                                .contains("readonly buffer VkFftInput { vec2 data[]; }")
                        );
                        assert!(
                            zero_shader
                                .glsl
                                .contains("buffer VkFftOutput { uint data[]; }")
                        );
                        assert!(zero_shader.glsl.contains("packHalf2x16("));
                    }
                    (Direction::Forward, ScalarType::F64, ScalarType::F32) => {
                        assert!(
                            zero_shader
                                .glsl
                                .contains("readonly buffer VkFftInput { vec2 data[]; }")
                        );
                        assert!(
                            zero_shader
                                .glsl
                                .contains("buffer VkFftOutput { dvec2 data[]; }")
                        );
                        assert!(zero_shader.glsl.contains("dvec2((vkfft_input.data"));
                    }
                    (Direction::Inverse, ScalarType::F64, ScalarType::F32) => {
                        assert!(
                            zero_shader
                                .glsl
                                .contains("readonly buffer VkFftInput { dvec2 data[]; }")
                        );
                        assert!(
                            zero_shader
                                .glsl
                                .contains("buffer VkFftOutput { vec2 data[]; }")
                        );
                        assert!(zero_shader.glsl.contains("= vec2("));
                    }
                    _ => unreachable!(),
                }
                for shader in shaders {
                    assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
                }
            }
        }
    }

    #[test]
    fn mixed_outer_passes_lower_and_compile_to_spirv() {
        let plan = FftPlan::build(FftConfig::new(vec![34]).with_batch_count(2)).unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::MixedRaderStockhamIr::build(&plan, Direction::Forward, device).unwrap();
        for pass in [&ir.pack_prime, &ir.twiddle_transpose, &ir.scatter_output] {
            let shader = VulkanGlslBackend.lower_mixed_pass(pass).unwrap();
            assert_eq!(shader.sequence_len, 34);
            assert_eq!(shader.batch_count, 2);
            assert_eq!(shader.descriptors.len(), 2);
            assert_eq!(shader.required_shared_memory_bytes, 0);
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
        let twiddle = VulkanGlslBackend
            .lower_mixed_pass(&ir.twiddle_transpose)
            .unwrap();
        assert!(twiddle.glsl.contains("float(n1 * k2) / float(VKFFT_N)"));
        assert!(twiddle.glsl.contains("uint source = n1 * VKFFT_P + k2"));
    }

    #[test]
    fn fft_rader_passes_lower_and_compile_to_spirv() {
        let plan = FftPlan::build(FftConfig::new(vec![17]).with_batch_count(2)).unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let pipeline = crate::RaderFftPipelineIr::build(&plan, Direction::Forward, device).unwrap();
        let gather = VulkanGlslBackend
            .lower_rader_fft_pass(&pipeline, &pipeline.gather)
            .unwrap();
        let multiply = VulkanGlslBackend
            .lower_rader_fft_pass(&pipeline, &pipeline.multiply)
            .unwrap();
        let scatter = VulkanGlslBackend
            .lower_rader_fft_pass(&pipeline, &pipeline.scatter)
            .unwrap();
        assert_eq!(gather.descriptors.len(), 2);
        assert_eq!(multiply.descriptors.len(), 3);
        assert_eq!(multiply.descriptors[2].role, BufferRole::LookupTable);
        assert_eq!(scatter.descriptors.len(), 3);
        assert_eq!(scatter.descriptors[2].role, BufferRole::Auxiliary);
        assert!(gather.glsl.contains("(VKFFT_COUNT - slot) % VKFFT_COUNT"));
        assert!(multiply.glsl.contains("vkfft_lut.data[slot]"));
        assert!(
            scatter
                .glsl
                .contains("vkfft_aux.data[vkfft_batch * VKFFT_P + 0u]")
        );
        for shader in [gather, multiply, scatter] {
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
    }

    #[test]
    fn explicit_fft_rader_gather_scatter_mixed_storage_compiles_end_to_end() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 8 * 1024;
        device.shared_memory_pow2_bytes = 8 * 1024;
        device.supports_f64 = true;

        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            let plan =
                FftPlan::build(FftConfig::new(vec![12_289]).with_precision(precision)).unwrap();
            let one_dim = crate::OneDimFftIr::build(&plan, Direction::Forward, device).unwrap();
            let crate::OneDimFftIr::Recursive(recursive) = &one_dim else {
                panic!("p12289 mixed-storage fallback should use recursive Rader IR");
            };
            let crate::RecursiveFftNodeIr::FftRader(pipeline) = &recursive.root else {
                panic!("p12289 mixed-storage fallback should keep an FFT-Rader root");
            };
            assert_eq!(pipeline.scalar, compute);
            assert_eq!(pipeline.input_storage_scalar, storage);
            assert_eq!(pipeline.output_storage_scalar, storage);
            assert_eq!(
                pipeline.input_strategy,
                RaderFftInputStrategy::GatherReversePass
            );
            assert!(
                pipeline
                    .forward_recursive()
                    .unwrap()
                    .four_step_plan
                    .is_some()
            );
            assert!(
                pipeline
                    .inverse_recursive()
                    .unwrap()
                    .four_step_plan
                    .is_some()
            );

            let program = crate::ProgramIr::one_dim_fft(&one_dim).unwrap();
            let shaders = VulkanGlslBackend.lower_one_dim_fft(&one_dim).unwrap();
            assert_eq!(shaders.len(), program.passes.len());

            let gather = shaders.first().unwrap();
            let scatter = shaders.last().unwrap();
            match (compute, storage) {
                (ScalarType::F32, ScalarType::F16) => {
                    assert!(
                        gather
                            .glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(gather.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(gather.glsl.contains("unpackHalf2x16("));
                    assert!(
                        scatter
                            .glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(scatter.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                    assert!(
                        scatter
                            .glsl
                            .contains("readonly buffer VkFftAuxiliary { uint data[]; }")
                    );
                    assert!(scatter.glsl.contains("packHalf2x16("));
                }
                (ScalarType::F64, ScalarType::F32) => {
                    assert!(
                        gather
                            .glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(gather.glsl.contains("buffer VkFftOutput { dvec2 data[]; }"));
                    assert!(
                        scatter
                            .glsl
                            .contains("readonly buffer VkFftInput { dvec2 data[]; }")
                    );
                    assert!(scatter.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(
                        scatter
                            .glsl
                            .contains("readonly buffer VkFftAuxiliary { vec2 data[]; }")
                    );
                }
                _ => unreachable!(),
            }
            for shader in shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn fft_rader_inverse_stockham_fuses_kernel_spectrum_lookup() {
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        for length in [17usize, 257] {
            let plan = FftPlan::build(FftConfig::new(vec![length]).with_batch_count(2)).unwrap();
            let pipeline =
                crate::RaderFftPipelineIr::build(&plan, Direction::Forward, device).unwrap();
            let fused = pipeline
                .fused_inverse_stockham_kernel()
                .unwrap()
                .expect("covered FFT-Rader inverse should remain a single Stockham root");
            assert_eq!(
                fused.input_modifier,
                StockhamInputModifier::MultiplyLookupTable
            );
            assert_eq!(fused.io_mapping, StockhamIoMapping::Contiguous);
            assert_eq!(fused.bindings.len(), 3);
            assert_eq!(fused.bindings[2].role, BufferRole::LookupTable);
            let shader = VulkanGlslBackend.lower(&fused).unwrap();
            assert_eq!(shader.descriptors.len(), 3);
            assert_eq!(shader.descriptors[2].role, BufferRole::LookupTable);
            assert!(shader.glsl.contains("vkfft_cmul("));
            assert!(shader.glsl.contains("vkfft_lut.data["));
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
            assert_eq!(spirv.descriptors.len(), 3);
        }
    }

    #[test]
    fn fft_rader_full_inverse_fuses_lookup_and_natural_scatter() {
        let mut device = full_subgroup_device();
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for precision in [Precision::F32, Precision::F64] {
            for length in [17usize, 257] {
                let plan = FftPlan::build(
                    FftConfig::new(vec![length])
                        .with_batch_count(2)
                        .with_precision(precision),
                )
                .unwrap();
                let pipeline =
                    crate::RaderFftPipelineIr::build(&plan, Direction::Forward, device).unwrap();
                let fused = pipeline
                    .fused_inverse_rader_kernel()
                    .unwrap()
                    .expect("covered FFT-Rader inverse should fuse lookup and scatter");
                assert_eq!(
                    fused.input_modifier,
                    StockhamInputModifier::MultiplyLookupTable
                );
                assert!(matches!(
                    fused.output_modifier,
                    StockhamOutputModifier::RaderScatter(_)
                ));
                let expected_bindings = if precision == Precision::F64 { 5 } else { 4 };
                assert_eq!(fused.bindings.len(), expected_bindings);
                assert_eq!(fused.bindings[2].role, BufferRole::LookupTable);
                assert_eq!(fused.bindings[3].role, BufferRole::Auxiliary);
                if precision == Precision::F64 {
                    assert_eq!(fused.bindings[4].role, BufferRole::TwiddleLookupTable);
                    assert_eq!(fused.twiddle_lut_len(), Some(length - 1));
                } else {
                    assert_eq!(fused.twiddle_lut_len(), None);
                }
                let shader = VulkanGlslBackend.lower(&fused).unwrap();
                assert_eq!(shader.descriptors.len(), expected_bindings);
                assert_eq!(shader.descriptors[2].role, BufferRole::LookupTable);
                assert_eq!(shader.descriptors[3].role, BufferRole::Auxiliary);
                if precision == Precision::F64 {
                    assert_eq!(shader.descriptors[4].role, BufferRole::TwiddleLookupTable);
                    assert!(
                        shader
                            .glsl
                            .contains(&format!("VKFFT_TWIDDLE_LUT_N = {}u", length - 1))
                    );
                    if length > 17 {
                        assert!(shader.glsl.contains("vkfft_twiddle_lut.data["));
                    }
                } else {
                    assert!(
                        !shader
                            .descriptors
                            .iter()
                            .any(|descriptor| descriptor.role == BufferRole::TwiddleLookupTable)
                    );
                }
                assert!(shader.glsl.contains("VKFFT_RADER_PERM"));
                assert!(shader.glsl.contains("vkfft_lut.data["));
                assert!(shader.glsl.contains("vkfft_aux.data["));
                assert!(shader.glsl.contains("vkfft_rader_dc"));
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
                assert_eq!(spirv.descriptors.len(), expected_bindings);
            }
        }
    }

    #[test]
    fn direct_rader_lowers_with_storage_lut_and_compiles_to_spirv() {
        let plan = FftPlan::build(FftConfig::new(vec![47]).with_batch_count(32)).unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let ir = crate::RaderDirectIr::build(&plan, Direction::Forward, device).unwrap();
        let shader = VulkanGlslBackend.lower_rader_direct(&ir).unwrap();
        assert_eq!(shader.sequence_len, 47);
        assert_eq!(shader.batch_count, 32);
        assert_eq!([shader.workgroup_size.x, shader.workgroup_size.y], [24, 5]);
        assert_eq!(shader.dispatch.x, 7);
        assert_eq!(shader.descriptors.len(), 3);
        assert_eq!(shader.descriptors[2].role, BufferRole::LookupTable);
        assert!(shader.glsl.contains("VKFFT_RADER_PERM[46]"));
        assert!(shader.glsl.contains("vkfft_lut.data[twiddle_index]"));
        assert!(shader.glsl.contains("VKFFT_GROUPED_BATCH = 5u"));
        assert!(shader.glsl.contains("VKFFT_BATCH_COUNT = 32u"));
        assert!(shader.glsl.contains("gl_LocalInvocationID.y"));
        assert!(
            shader
                .glsl
                .contains("if (vkfft_batch >= VKFFT_BATCH_COUNT) return")
        );
        let spirv = shader.compile_spirv().unwrap();
        assert_eq!(spirv.words[0], 0x0723_0203);
        assert_eq!(spirv.descriptors.len(), 3);
    }

    #[test]
    fn direct_rader_mixed_storage_lowers_external_boundaries_only() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        for (compute_precision, compute, storage) in [
            (Precision::F32, ScalarType::F32, ScalarType::F16),
            (Precision::F64, ScalarType::F64, ScalarType::F32),
        ] {
            let plan = FftPlan::build(
                FftConfig::new(vec![47])
                    .with_batch_count(2)
                    .with_precision(compute_precision),
            )
            .unwrap();
            let ir = crate::RaderDirectIr::build(&plan, Direction::Forward, device)
                .unwrap()
                .with_external_input_storage_scalar(storage)
                .unwrap()
                .with_external_output_storage_scalar(storage)
                .unwrap();
            assert_eq!(ir.scalar, compute);
            assert_eq!(ir.input_storage_scalar, storage);
            assert_eq!(ir.output_storage_scalar, storage);
            let shader = VulkanGlslBackend.lower_rader_direct(&ir).unwrap();
            assert_eq!(shader.scalar, compute);
            assert!(shader.glsl.contains("vkfft_lut.data[twiddle_index]"));
            match (compute, storage) {
                (ScalarType::F32, ScalarType::F16) => {
                    assert!(
                        shader
                            .glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(shader.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                    assert!(shader.glsl.contains("unpackHalf2x16(vkfft_input.data"));
                    assert!(shader.glsl.contains("packHalf2x16(sum)"));
                }
                (ScalarType::F64, ScalarType::F32) => {
                    assert!(
                        shader
                            .glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(shader.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(shader.glsl.contains("dvec2((vkfft_input.data"));
                    assert!(shader.glsl.contains("= vec2((sum).x, (sum).y)"));
                }
                _ => unreachable!(),
            }
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
            assert_eq!(spirv.descriptors.len(), 3);
        }
    }

    #[test]
    fn fft_rader_mixed_storage_lowers_generator_and_scatter_boundaries_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            let plan = FftPlan::build(FftConfig::new(vec![19]).with_precision(precision)).unwrap();
            let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
            let crate::RecursiveFftNodeIr::FftRader(rader) = &ir.root else {
                panic!("p19 mixed-storage plan should keep an FFT-Rader root");
            };
            assert_eq!(rader.input_storage_scalar, storage);
            assert_eq!(rader.output_storage_scalar, storage);
            let program = crate::ProgramIr::recursive_fft(&ir).unwrap();
            assert_eq!(program.input_resource().unwrap().scalar, storage);
            assert_eq!(program.output_resource().unwrap().scalar, storage);
            assert!(program.resources.iter().all(|resource| {
                matches!(
                    resource.kind,
                    crate::ProgramResourceKind::Input | crate::ProgramResourceKind::Output
                ) || resource.scalar == compute
            }));

            let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
            assert_eq!(shaders.len(), 2);
            assert_eq!(shaders.len(), program.passes.len());
            let forward = &shaders[0];
            let inverse = &shaders[1];
            assert_eq!(forward.scalar, compute);
            assert_eq!(inverse.scalar, compute);
            match storage {
                ScalarType::F16 => {
                    assert!(
                        forward
                            .glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(forward.glsl.contains("unpackHalf2x16(vkfft_input.data"));
                    assert!(inverse.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                    assert!(
                        inverse
                            .glsl
                            .contains("readonly buffer VkFftAuxiliary { uint data[]; }")
                    );
                    assert!(inverse.glsl.contains("unpackHalf2x16(vkfft_aux.data"));
                    assert!(inverse.glsl.contains("packHalf2x16("));
                }
                ScalarType::F32 => {
                    assert!(
                        forward
                            .glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(forward.glsl.contains("dvec2((vkfft_input.data"));
                    assert!(inverse.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(
                        inverse
                            .glsl
                            .contains("readonly buffer VkFftAuxiliary { vec2 data[]; }")
                    );
                    assert!(inverse.glsl.contains("dvec2((vkfft_aux.data"));
                }
                _ => unreachable!(),
            }
            for shader in shaders {
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn bluestein_passes_lower_and_compile_to_spirv() {
        let mut bluestein_tuning = crate::PlannerTuning::portable();
        bluestein_tuning.max_rader_fft_prime = 100;
        let plan = FftPlan::build(
            FftConfig::new(vec![103])
                .with_batch_count(2)
                .with_tuning(bluestein_tuning),
        )
        .unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        let pipeline =
            crate::BluesteinPipelineIr::build(&plan, Direction::Forward, device).unwrap();
        for pass in [
            &pipeline.preprocess,
            &pipeline.multiply,
            &pipeline.postprocess,
        ] {
            let shader = VulkanGlslBackend.lower_bluestein_pass(pass).unwrap();
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(shader.sequence_len, pipeline.convolution_len);
            assert_eq!(shader.batch_count, 2);
            assert_eq!(shader.dispatch.x, 2);
            assert_eq!(shader.required_shared_memory_bytes, 0);
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
        let preprocess = VulkanGlslBackend
            .lower_bluestein_pass(&pipeline.preprocess)
            .unwrap();
        assert_eq!(preprocess.descriptors.len(), 2);
        let multiply = VulkanGlslBackend
            .lower_bluestein_pass(&pipeline.multiply)
            .unwrap();
        assert_eq!(multiply.descriptors.len(), 3);
        assert_eq!(multiply.descriptors[2].binding, 2);
        assert_eq!(multiply.descriptors[2].role, BufferRole::LookupTable);
        assert_eq!(multiply.descriptors[2].access, BufferAccess::ReadOnly);
        assert!(
            multiply
                .glsl
                .contains("layout(set = 0, binding = 2, std430) readonly buffer VkFftLookupTable")
        );
        assert!(multiply.glsl.contains("vkfft_lut.data[i]"));
        assert!(!multiply.glsl.contains("VKFFT_BLUESTEIN_KERNEL"));
    }

    #[test]
    fn grouped_bluestein_tail_and_zero_pad_compile_to_spirv() {
        let mut tuning = crate::PlannerTuning::portable();
        tuning.max_rader_fft_prime = 100;
        let plan = FftPlan::build(
            FftConfig::new(vec![103])
                .with_batch_count(7)
                .with_grouped_batch(0, 3)
                .unwrap()
                .with_precision(Precision::F16StorageF32Compute)
                .with_tuning(tuning)
                .with_zero_padding(0, 19, 31)
                .unwrap(),
        )
        .unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        let one_dim = crate::OneDimFftIr::build(&plan, Direction::Forward, device).unwrap();
        let crate::OneDimFftIr::Bluestein(pipeline) = &one_dim else {
            panic!("forced grouped p103 should use Bluestein");
        };
        let program = crate::ProgramIr::one_dim_fft(&one_dim).unwrap();
        let shaders = VulkanGlslBackend.lower_one_dim_fft(&one_dim).unwrap();
        assert_eq!(shaders.len(), program.passes.len());
        assert!(shaders.iter().all(|shader| shader.dispatch.x == 3));
        let zero = shaders.first().unwrap();
        assert!(zero.glsl.contains("VKFFT_GROUPED_BATCH = 3u"));
        assert!(zero.glsl.contains("VKFFT_BATCH_COUNT = 7u"));
        assert!(zero.glsl.contains("vkfft_batch_end = min"));
        let preprocess = VulkanGlslBackend
            .lower_bluestein_pass(&pipeline.preprocess)
            .unwrap();
        assert_eq!(preprocess.dispatch.x, 3);
        assert!(preprocess.glsl.contains("VKFFT_GROUPED_BATCH = 3u"));
        assert!(preprocess.glsl.contains("VKFFT_BATCH_COUNT = 7u"));
        let multiply = VulkanGlslBackend
            .lower_bluestein_pass(&pipeline.multiply)
            .unwrap();
        assert_eq!(multiply.dispatch.x, 3);
        assert!(multiply.glsl.contains("VKFFT_GROUPED_BATCH = 3u"));
        for shader in shaders.iter().chain([&multiply]) {
            assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
        }
    }

    #[test]
    fn mixed_storage_bluestein_boundaries_compile_to_spirv() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        let mut tuning = crate::PlannerTuning::portable();
        tuning.max_rader_fft_prime = 100;

        for (precision, compute, storage) in [
            (
                Precision::F16StorageF32Compute,
                ScalarType::F32,
                ScalarType::F16,
            ),
            (
                Precision::F64ComputeF32Storage,
                ScalarType::F64,
                ScalarType::F32,
            ),
        ] {
            let plan = FftPlan::build(
                FftConfig::new(vec![103])
                    .with_precision(precision)
                    .with_tuning(tuning),
            )
            .unwrap();
            let one_dim = crate::OneDimFftIr::build(&plan, Direction::Forward, device).unwrap();
            let crate::OneDimFftIr::Bluestein(pipeline) = &one_dim else {
                panic!("forced p103 mixed-storage plan did not build Bluestein");
            };
            assert_eq!(pipeline.scalar, compute);
            assert_eq!(pipeline.external_storage_scalar(), storage);
            let program = crate::ProgramIr::one_dim_fft(&one_dim).unwrap();
            assert_eq!(program.input_resource().unwrap().scalar, storage);
            assert_eq!(program.output_resource().unwrap().scalar, storage);
            let shaders = VulkanGlslBackend.lower_one_dim_fft(&one_dim).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let first = shaders.first().unwrap();
            let last = shaders.last().unwrap();
            match (compute, storage) {
                (ScalarType::F32, ScalarType::F16) => {
                    assert!(
                        first
                            .glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(first.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(first.glsl.contains("unpackHalf2x16("));
                    assert!(
                        last.glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(last.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                    assert!(last.glsl.contains("packHalf2x16("));
                }
                (ScalarType::F64, ScalarType::F32) => {
                    assert!(
                        first
                            .glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(first.glsl.contains("buffer VkFftOutput { dvec2 data[]; }"));
                    assert!(first.glsl.contains("dvec2((vkfft_input.data"));
                    assert!(
                        last.glsl
                            .contains("readonly buffer VkFftInput { dvec2 data[]; }")
                    );
                    assert!(last.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                }
                _ => unreachable!(),
            }
            for shader in shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn frequency_zero_padding_vulkan_order_matches_program_for_one_dim_and_nd() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.supports_f64 = true;

        for direction in [Direction::Forward, Direction::Inverse] {
            let plan = FftPlan::build(
                FftConfig::new(vec![64])
                    .with_batch_count(2)
                    .with_precision(Precision::F16StorageF32Compute)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(0, 16, 32)
                    .unwrap()
                    .with_zero_padding_domain(ZeroPaddingDomain::Frequency),
            )
            .unwrap();
            let ir = OneDimFftIr::build(&plan, direction, device).unwrap();
            let program = crate::ProgramIr::one_dim_fft(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_one_dim_fft(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let zero_index = if direction == Direction::Forward {
                shaders.len() - 1
            } else {
                0
            };
            assert!(shaders[zero_index].glsl.contains("VKFFT_ZERO_PAD_LEFT"));
            let core_index = if direction == Direction::Forward {
                0
            } else {
                shaders.len() - 1
            };
            let core = &shaders[core_index];
            let zero = &shaders[zero_index];
            match direction {
                Direction::Forward => {
                    assert!(
                        core.glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(core.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(
                        zero.glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(zero.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                }
                Direction::Inverse => {
                    assert!(
                        zero.glsl
                            .contains("readonly buffer VkFftInput { uint data[]; }")
                    );
                    assert!(zero.glsl.contains("buffer VkFftOutput { vec2 data[]; }"));
                    assert!(
                        core.glsl
                            .contains("readonly buffer VkFftInput { vec2 data[]; }")
                    );
                    assert!(core.glsl.contains("buffer VkFftOutput { uint data[]; }"));
                }
            }
            assert!(
                program.passes[zero_index]
                    .name
                    .contains(if direction == Direction::Forward {
                        "zero_pad_forward_output"
                    } else {
                        "zero_pad_inverse_input"
                    })
            );
            for shader in &shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }

        for direction in [Direction::Forward, Direction::Inverse] {
            let plan = FftPlan::build(
                FftConfig::new(vec![3, 4])
                    .with_precision(Precision::F64ComputeF32Storage)
                    .with_inverse_normalization(direction == Direction::Inverse)
                    .with_zero_padding(1, 2, 4)
                    .unwrap()
                    .with_zero_padding_domain(ZeroPaddingDomain::Frequency),
            )
            .unwrap();
            let ir = NdFftIr::build(&plan, direction, device).unwrap();
            let zero = ir.zero_pad_pass.as_ref().unwrap();
            match direction {
                Direction::Forward => {
                    assert_eq!(zero.input_storage_scalar, ScalarType::F64);
                    assert_eq!(zero.output_storage_scalar, ScalarType::F32);
                    assert_eq!(ir.axes[0].pack.input_storage_scalar, ScalarType::F32);
                    assert_eq!(
                        ir.axes.last().unwrap().scatter.output_storage_scalar,
                        ScalarType::F64
                    );
                }
                Direction::Inverse => {
                    assert_eq!(zero.input_storage_scalar, ScalarType::F32);
                    assert_eq!(zero.output_storage_scalar, ScalarType::F64);
                    assert_eq!(ir.axes[0].pack.input_storage_scalar, ScalarType::F64);
                    assert_eq!(
                        ir.axes.last().unwrap().scatter.output_storage_scalar,
                        ScalarType::F32
                    );
                }
            }
            let program = crate::ProgramIr::nd_fft(&ir).unwrap();
            let shaders = VulkanGlslBackend.lower_nd_fft(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let zero_index = if direction == Direction::Forward {
                shaders.len() - 1
            } else {
                0
            };
            assert!(shaders[zero_index].glsl.contains("vkfft_zero_i"));
            assert!(
                program.passes[zero_index]
                    .name
                    .contains(if direction == Direction::Forward {
                        "zero_pad_forward_output"
                    } else {
                        "zero_pad_inverse_input"
                    })
            );
            assert_eq!(
                shaders[zero_index].compile_spirv().unwrap().words[0],
                0x0723_0203
            );
        }
    }

    #[test]
    fn zero_padding_boundary_lowers_for_f32_and_f64_and_wraps_one_dim_program() {
        for precision in [Precision::F32, Precision::F64] {
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.supports_f64 = true;
            let config = FftConfig::new(vec![64])
                .with_precision(precision)
                .with_zero_padding(0, 32, 64)
                .unwrap();
            let plan = FftPlan::build(config).unwrap();
            let ir = OneDimFftIr::build(&plan, Direction::Forward, device).unwrap();
            let shaders = VulkanGlslBackend.lower_one_dim_fft(&ir).unwrap();
            let program = crate::ProgramIr::one_dim_fft(&ir).unwrap();
            assert_eq!(shaders.len(), program.passes.len());
            let zero = &shaders[0];
            assert!(zero.glsl.contains("VKFFT_ZERO_PAD_LEFT"));
            assert!(zero.glsl.contains("VKFFT_ZERO_PAD_RIGHT"));
            assert!(zero.glsl.contains("vkfft_zero_i >= VKFFT_ZERO_PAD_LEFT"));
            assert!(
                zero.glsl
                    .contains("vkfft_output.data[vkfft_zero_base + vkfft_zero_i]")
            );
            let spirv = zero.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
            assert_eq!(zero.descriptors.len(), 2);
            assert_eq!(zero.descriptors[0].role, BufferRole::Input);
            assert_eq!(zero.descriptors[1].role, BufferRole::Output);
        }
    }

