    #[test]
    fn odd_radix_fixed_butterflies_cover_register_and_fallback_lowering() {
        for (precision, expected_scalar) in [
            (Precision::F32, ScalarType::F32),
            (Precision::F64, ScalarType::F64),
        ] {
            let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
            device.shared_memory_bytes = 128 * 1024;
            device.shared_memory_pow2_bytes = 128 * 1024;
            device.max_threads_per_block = 1024;
            device.supports_f64 = true;
            for radix in [3usize, 5, 7, 11, 13] {
                let ir = crate::kernel_ir::synthetic_odd_radix_register_kernel(
                    radix,
                    Direction::Forward,
                    precision,
                    false,
                    device,
                )
                .unwrap();
                let shader = VulkanGlslBackend.lower(&ir).unwrap();
                assert!(shader.glsl.contains(&format!("radix{radix}_stage_0")));
                assert!(
                    !shader
                        .glsl
                        .contains(&format!("vkfft_generic_results_0[{radix}]"))
                );
                assert!(!shader.glsl.contains("radix_angle"));
                if matches!(radix, 11 | 13) {
                    assert!(shader.glsl.contains(&format!(
                        "VkFFT radix-{radix} primitive-root permutation/FMA structure"
                    )));
                    assert!(shader.glsl.contains("_positive0"));
                    assert!(shader.glsl.contains("_conjugate0"));
                    assert!(shader.glsl.contains("VKFFT_SIGN"));
                }
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
                assert_eq!(spirv.scalar, expected_scalar);
            }
        }

        for radix in [3usize, 5, 7, 11, 13] {
            let plan = FftPlan::build(FftConfig::new(vec![radix])).unwrap();
            let device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Amd);
            let ir = KernelIr::stockham_1d(&plan, Direction::Forward, device).unwrap();
            assert_eq!(
                ir.execution_layout,
                StockhamExecutionLayout::RegisterSingleShared
            );
            let shader = VulkanGlslBackend.lower(&ir).unwrap();
            assert_eq!(shader.required_shared_memory_bytes, 0);
            assert!(shader.glsl.contains(&format!("radix{radix}_stage_0")));
            assert!(!shader.glsl.contains("float radix_angle"));
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
    }

