    #[test]
    fn dd_large_shared_single_upload_above_4096_lowers_with_upstream_axis_blocks() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 164 * 1024;
        device.shared_memory_pow2_bytes = 164 * 1024;
        device.max_threads_per_block = 1024;
        device.max_workgroup_size = [1024, 1024, 64];
        device.supports_f64 = true;

        for (length, expected_threads) in [
            (4_800usize, 960u32),
            (5_000usize, 625u32),
            (5_120usize, 640u32),
        ] {
            let config = FftConfig::new(vec![length]).with_precision(Precision::DoubleDouble);
            let plan = FftPlan::build_for_device(config, device).unwrap();
            let ir =
                crate::DoubleDoubleOneDimIr::build_for_device(&plan, Direction::Forward, device)
                    .unwrap();
            let crate::DoubleDoubleOneDimIr::Stockham(stockham) = &ir else {
                panic!("N{length} should lower as a device-aware single-upload DD Stockham plan");
            };
            let shaders = VulkanGlslBackend
                .lower_double_double_one_dim_program(&ir)
                .unwrap();
            assert_eq!(shaders.len(), stockham.stages.len() + 2);
            for shader in shaders {
                assert_eq!(shader.workgroup_size.x, expected_threads);
                assert_eq!(shader.workgroup_size.y, 1);
                let spirv = shader.compile_spirv().unwrap();
                assert_eq!(spirv.words[0], 0x0723_0203);
            }

            let batch_config = FftConfig::new(vec![length])
                .with_batch_count(32)
                .with_precision(Precision::DoubleDouble);
            let batch_plan = FftPlan::build_for_device(batch_config, device).unwrap();
            let batch_ir = crate::DoubleDoubleOneDimIr::build_for_device(
                &batch_plan,
                Direction::Forward,
                device,
            )
            .unwrap();
            let batch_shaders = VulkanGlslBackend
                .lower_double_double_one_dim_program(&batch_ir)
                .unwrap();
            assert!(!batch_shaders.is_empty());
            for shader in batch_shaders {
                assert_eq!(shader.workgroup_size.x, expected_threads);
                assert_eq!(shader.workgroup_size.y, 1);
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }

            let nd_config = FftConfig::new(vec![length, 8])
                .with_batch_count(5)
                .with_precision(Precision::DoubleDouble);
            let nd = crate::TransformIr::build(nd_config, Direction::Forward, device).unwrap();
            let crate::TransformIr::ComplexNdDoubleDouble(nd) = nd else {
                panic!("DD [N{length},8] should remain ND C2C");
            };
            let nd_shaders = VulkanGlslBackend.lower_double_double_nd(&nd).unwrap();
            let long_axis_stages = nd_shaders
                .iter()
                .filter(|shader| {
                    shader.sequence_len == length && shader.glsl.contains("Stockham stage")
                })
                .collect::<Vec<_>>();
            assert!(!long_axis_stages.is_empty());
            for shader in long_axis_stages {
                assert_eq!(shader.workgroup_size.x, 1);
                assert_eq!(shader.workgroup_size.y, expected_threads);
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

