            device.shared_memory_bytes = 48 * 1024;
            device.shared_memory_pow2_bytes = 32 * 1024;
            device.max_threads_per_block = 1024;
            device.supports_f64 = true;
            let ir = KernelIr::stockham_1d(&plan, Direction::Forward, device).unwrap();
            assert_eq!(
                ir.execution_layout,
                crate::StockhamExecutionLayout::RegisterBoostSingleShared
            );
            let schedule = ir.scheduler_hint.as_ref().unwrap();
            assert_eq!(schedule.register_boost, 2);
            assert_eq!(schedule.stage_radices.last().copied(), Some(2));
            assert_eq!(
                ir.stockham_shared_layout.unwrap().logical_elements,
                expected_shared_elements
            );
            let shader = VulkanGlslBackend.lower(&ir).unwrap();
