    #[test]
    fn two_upload_four_step_lowering_fuses_strided_gather_twiddle_and_natural_scatter() {
        let length = 1_048_576usize;
        let plan = FftPlan::build(FftConfig::new(vec![length])).unwrap();
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 48 * 1024;
        device.shared_memory_pow2_bytes = 48 * 1024;
        device.max_threads_per_block = 1024;
        let ir = crate::RecursiveFftIr::build(&plan, Direction::Forward, device).unwrap();
        assert!(ir.four_step_plan.is_some());
        let shaders = VulkanGlslBackend.lower_recursive_fft(&ir).unwrap();
        assert_eq!(shaders.len(), 2);

        assert_eq!(
            [shaders[0].workgroup_size.x, shaders[0].workgroup_size.y],
            [4, 128]
        );
        assert_eq!(
            [shaders[1].workgroup_size.x, shaders[1].workgroup_size.y],
            [4, 128]
        );
        assert_eq!([shaders[0].dispatch.x, shaders[1].dispatch.x], [256, 256]);
        let first = &shaders[0].glsl;
        assert!(first.contains("VKFFT_FOUR_STEP_FULL_N = 1048576u"));
        assert!(first.contains("VKFFT_FOUR_STEP_A = 1024u"));
        assert!(first.contains("vkfft_batch / VKFFT_FOUR_STEP_A"));
        assert!(first.contains("VKFFT_FOUR_STEP_A * (input_index_0)"));
        assert!(first.contains("VKFFT_SIGN * VKFFT_TAU * float(vkfft_four_step_lane * ("));
        assert!(
            !shaders[0]
                .descriptors
                .iter()
                .any(|descriptor| descriptor.role == BufferRole::TwiddleLookupTable)
        );
        assert!(first.contains("VKFFT_FOUR_STEP_B + (output_index_0)"));

        let second = &shaders[1].glsl;
        assert!(second.contains("vkfft_batch / VKFFT_FOUR_STEP_B"));
        assert!(second.contains("VKFFT_FOUR_STEP_B * (output_index_0)"));
        assert!(!second.contains("VKFFT_SIGN * VKFFT_TAU * float(vkfft_four_step_lane * ("));
        for shader in shaders {
            let spirv = shader.compile_spirv().unwrap();
            assert_eq!(spirv.words[0], 0x0723_0203);
        }
    }

