    #[test]
    fn double_double_r2r_spatial_zero_padding_is_fused_into_external_boundaries() {
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            let base_config = FftConfig::new(vec![9])
                .with_batch_count(7)
                .with_precision(precision)
                .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                .with_grouped_batch(0, 3)
                .unwrap();
            let forward = crate::DoubleDoubleR2rIr::build(
                &FftPlan::build(base_config.clone().with_zero_padding(0, 3, 6).unwrap()).unwrap(),
                Direction::Forward,
            )
            .unwrap();
            let baseline = crate::DoubleDoubleR2rIr::build(
                &FftPlan::build(base_config.clone()).unwrap(),
                Direction::Forward,
            )
            .unwrap();
            let forward_program = crate::ProgramIr::double_double_r2r(&forward).unwrap();
            let baseline_program = crate::ProgramIr::double_double_r2r(&baseline).unwrap();
            assert_eq!(forward_program.passes.len(), baseline_program.passes.len());
            let forward_shaders = VulkanGlslBackend.lower_double_double_r2r(&forward).unwrap();
            assert_eq!(forward_shaders.len(), forward_program.passes.len());
            let preprocess = forward_shaders.first().unwrap();
            assert!(preprocess.glsl.contains("vkfft_dd_r2r_external_load"));
            assert!(preprocess.glsl.contains("(logical) >= 3u"));
            assert!(preprocess.glsl.contains("(logical) < 6u"));
            assert!(
                !forward_shaders
                    .last()
                    .unwrap()
                    .glsl
                    .contains("for (uint k = 3u; k < 6u; ++k)")
            );
            for shader in &forward_shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }

            let inverse = crate::DoubleDoubleR2rIr::build(
                &FftPlan::build(
                    base_config
                        .with_inverse_normalization(true)
                        .with_zero_padding(0, 3, 6)
                        .unwrap(),
                )
                .unwrap(),
                Direction::Inverse,
            )
            .unwrap();
            let inverse_shaders = VulkanGlslBackend.lower_double_double_r2r(&inverse).unwrap();
            assert!(
                !inverse_shaders
                    .first()
                    .unwrap()
                    .glsl
                    .contains("(logical) >= 3u")
            );
            assert!(
                inverse_shaders
                    .last()
                    .unwrap()
                    .glsl
                    .contains("for (uint k = 3u; k < 6u; ++k)")
            );
            for shader in &inverse_shaders {
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn double_double_type_ii_iii_physical_stockham_fuses_r2r_boundaries() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for transform in [
                crate::TransformKind::Dct(crate::DctType::II),
                crate::TransformKind::Dct(crate::DctType::III),
                crate::TransformKind::Dst(crate::DstType::II),
                crate::TransformKind::Dst(crate::DstType::III),
            ] {
                let config = FftConfig::new(vec![16])
                    .with_batch_count(5)
                    .with_precision(precision)
                    .with_transform(transform)
                    .with_grouped_batch(0, 3)
                    .unwrap()
                    .resolve_tuning_for_device(device);
                let plan = FftPlan::build_for_device(config, device).unwrap();
                let ir =
                    crate::DoubleDoubleR2rIr::build_for_device(&plan, Direction::Forward, device)
                        .unwrap();
                let crate::DoubleDoubleR2rAlgorithm::FftReduction { fft, .. } = &ir.algorithm
                else {
                    panic!("DD Type-II/III N16 must use FFT reduction");
                };
                let crate::DoubleDoubleOneDimIr::Stockham(stockham) = fft.as_ref() else {
                    panic!("DD Type-II/III N16 must retain monolithic Stockham child");
                };
                let block = stockham
                    .axis_batch_block
                    .expect("device-aware DD Type-II/III N16 physical block");
                let program = crate::ProgramIr::double_double_r2r(&ir).unwrap();
                assert_eq!(program.passes.len(), 1);
                assert_eq!(
                    program.passes[0].dispatch.x as usize,
                    stockham.batch_group_count()
                );
                assert!(program.passes[0].name.contains("stockham_fused_16"));
                assert!(program.resources.iter().all(|resource| {
                    !resource.name.contains("r2r_fft_input")
                        && !resource.name.contains("r2r_fft_output")
                }));
                assert!(program.resources.iter().any(|resource| {
                    resource.name == "double_double_r2r_phases" && resource.elements == 16
                }));
                let shaders = VulkanGlslBackend.lower_double_double_r2r(&ir).unwrap();
                assert_eq!(shaders.len(), 1);
                let shader = &shaders[0];
                assert_eq!(shader.dispatch, program.passes[0].dispatch);
                assert_eq!(
                    shader.workgroup_size,
                    WorkgroupSize {
                        x: block.local_size_x as u32,
                        y: block.local_size_y as u32,
                        z: 1,
                    }
                );
                assert!(
                    shader.glsl.contains(
                        "fused DD R2R Type-II/III boundary + physical monolithic Stockham"
                    )
                );
                assert!(
                    shader
                        .descriptors
                        .iter()
                        .any(|descriptor| descriptor.binding == 3
                            && descriptor.role == BufferRole::LookupTable)
                );
                assert_eq!(shader.descriptors.len(), program.passes[0].bindings.len());
                assert_eq!(shader.compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

    #[test]
    fn double_double_type_ii_n512_physical_stockham_fusion_uses_valid_shared_budget() {
        let mut device = DeviceProfile::generic(Backend::Vulkan, GpuVendor::Nvidia);
        device.shared_memory_bytes = 128 * 1024;
        device.shared_memory_pow2_bytes = 128 * 1024;
        device.supports_f64 = true;
        for precision in [Precision::DoubleDouble, Precision::DoubleDoubleF64Storage] {
            for direction in [Direction::Forward, Direction::Inverse] {
                let config = FftConfig::new(vec![512])
                    .with_batch_count(5)
                    .with_precision(precision)
                    .with_transform(crate::TransformKind::Dct(crate::DctType::II))
                    .with_grouped_batch(0, 3)
                    .unwrap()
                    .resolve_tuning_for_device(device);
                let plan = FftPlan::build_for_device(config, device).unwrap();
                let ir =
                    crate::DoubleDoubleR2rIr::build_for_device(&plan, direction, device).unwrap();
                let crate::DoubleDoubleR2rAlgorithm::FftReduction { fft, .. } = &ir.algorithm
                else {
                    panic!("DD DCT-II N512 must use FFT reduction");
                };
                let crate::DoubleDoubleOneDimIr::Stockham(stockham) = fft.as_ref() else {
                    panic!("DD DCT-II N512 must retain single-upload Stockham child");
                };
                let block = stockham
                    .axis_batch_block
                    .expect("device-aware DD DCT-II N512 physical block");
                let expected_shared = stockham.sequence_len * block.grouped_batch * 32;
                assert!(expected_shared <= device.shared_memory_bytes);
                let program = crate::ProgramIr::double_double_r2r(&ir).unwrap();
                assert_eq!(program.passes.len(), 1);
                assert!(program.passes[0].name.contains("stockham_fused_512"));
                let shaders = VulkanGlslBackend.lower_double_double_r2r(&ir).unwrap();
                assert_eq!(shaders.len(), 1);
                assert_eq!(shaders[0].required_shared_memory_bytes, expected_shared);
                assert_eq!(shaders[0].dispatch, program.passes[0].dispatch);
                assert_eq!(shaders[0].compile_spirv().unwrap().words[0], 0x0723_0203);
            }
        }
    }

